{"command":"cd /workspace && cat > internal/cli/cli.go <<'EOF'
package cli

import (
	"fmt"
	"log"
	"os"
)

const appVersion = "v0.0.0-SNAPSHOT"

type command struct {
	name        string
	description string
	run         func(args []string) error
}

func commands() []command {
	return []command{
		{name: "check", description: "run linter over specified targets", run: runCheck},
		{name: "doc", description: "get installed checkers documentation", run: runDoc},
		{name: "help", description: "shows help message", run: runHelp},
		{name: "version", description: "shows version of the application", run: runVersion},
	}
}

// Main runs the CLI and returns the process exit code.
func Main(args []string) int {
	if len(args) == 0 {
		log.Println("no args provided")
		return 0
	}
	name := args[0]
	if name == "" {
		name = "check"
	}
	cmds := commands()
	for _, c := range cmds {
		if c.name == name {
			if err := c.run(args[1:]); err != nil {
				log.Println(err)
			}
			return 0
		}
	}
	msg := fmt.Sprintf("%q unknown command", name)
	if s := suggestCommand(name, cmds); s != "" {
		msg += fmt.Sprintf(", did you mean %q?", s)
	}
	fmt.Fprintf(os.Stdout, "%s\nRun \"go-critic help\" for usage.\n\n", msg)
	log.Printf("no such command %q", name)
	return 0
}

func suggestCommand(got string, cmds []command) string {
	const maxDist = 2
	best := maxDist + 1
	match := ""
	for _, c := range cmds {
		d := levenshtein(got, c.name)
		if d < best {
			best = d
			match = c.name
		}
	}
	return match
}

func levenshtein(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	prev := make([]int, len(rb)+1)
	cur := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			v := prev[j] + 1
			if cur[j-1]+1 < v {
				v = cur[j-1] + 1
			}
			if prev[j-1]+cost < v {
				v = prev[j-1] + cost
			}
			cur[j] = v
		}
		prev, cur = cur, prev
	}
	return prev[len(rb)]
}

func runHelp(args []string) error {
	fmt.Fprintf(os.Stdout, "Usage:\n\n    go-critic <command> [arguments...]\n\nThe commands are:\n\n")
	for _, c := range commands() {
		fmt.Fprintf(os.Stdout, "    %-17s %s\n", c.name, c.description)
	}
	fmt.Fprintf(os.Stdout, "\nVersion: %s\n\n", appVersion)
	return nil
}

func runVersion(args []string) error {
	fmt.Fprintf(os.Stdout, "go-critic version: %s\n\n", appVersion)
	return nil
}
EOF
echo ok"}

