{"command":"cd /workspace && cat > internal/cli/doc.go <<'EOF'
package cli

import (
	"flag"
	"fmt"
	"log"
	"os"
	"strings"

	"github.com/gocritic-reimpl/gocritic/internal/lint"
)

func runDoc(args []string) error {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	if err := fs.Parse(args); err != nil {
		return err
	}
	switch fs.NArg() {
	case 0:
		for _, info := range lint.AllCheckers() {
			fmt.Fprintf(os.Stdout, "%s [%s]\n", info.Name, strings.Join(info.Tags, " "))
		}
	case 1:
		name := fs.Arg(0)
		info := lint.FindChecker(name)
		if info == nil {
			log.Fatalf("checker with name %q not found", name)
		}
		var b strings.Builder
		fmt.Fprintf(&b, "%s checker documentation\n", info.Name)
		fmt.Fprintf(&b, "URL: https://github.com/go-critic/go-critic/checkers\n")
		fmt.Fprintf(&b, "Tags: [%s]\n\n", strings.Join(info.Tags, " "))
		b.WriteString(info.Doc)
		if len(info.Params) != 0 {
			b.WriteString("\nChecker parameters:\n")
			for _, p := range info.Params {
				fmt.Fprintf(&b, "  -@%s.%s %s\n    \t%s (default %s)\n", info.Name, p.Name, p.Type, p.Usage, p.Default)
			}
		}
		os.Stdout.WriteString(b.String())
	default:
		log.Fatalf("expected 0 or 1 positional arguments")
	}
	return nil
}
EOF
echo"}

