{"command":"cd /workspace && cat > internal/lint/lint.go <<'EOF'
package lint

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/printer"
	"go/token"
	"go/types"
	"sort"
	"strings"
)

// ParamInfo describes a single checker parameter.
type ParamInfo struct {
	Name    string
	Type    string // "int", "bool" or "string"
	Default string
	Usage   string
}

// CheckerInfo holds checker metadata.
type CheckerInfo struct {
	Name   string
	Tags   []string
	Doc    string
	Params []ParamInfo
}

// HasTag reports whether checker has the given tag.
func (info *CheckerInfo) HasTag(tag string) bool {
	for _, t := range info.Tags {
		if t == tag {
			return true
		}
	}
	return false
}

// AllCheckers returns all known checkers sorted by name.
func AllCheckers() []*CheckerInfo {
	res := make([]*CheckerInfo, 0, len(checkerDocs))
	for i := range checkerDocs {
		res = append(res, &checkerDocs[i])
	}
	sort.Slice(res, func(i, j int) bool { return res[i].Name < res[j].Name })
	return res
}

// FindChecker finds checker info by its name.
func FindChecker(name string) *CheckerInfo {
	for i := range checkerDocs {
		if checkerDocs[i].Name == name {
			return &checkerDocs[i]
		}
	}
	return nil
}

// Warning is a single linter report.
type Warning struct {
	Pos  token.Pos
	Text string
}

// GoVersion is a parsed go version.
type GoVersion struct {
	Major int
	Minor int
}

// GreaterOrEqual reports whether v >= other.
func (v GoVersion) GreaterOrEqual(other GoVersion) bool {
	if v.Major == 0 && v.Minor == 0 {
		return true // latest
	}
	if v.Major != other.Major {
		return v.Major > other.Major
	}
	return v.Minor >= other.Minor
}

// Context holds per-package and per-file state.
type Context struct {
	Fset      *token.FileSet
	Pkg       *types.Package
	TypesInfo *types.Info
	Sizes     types.Sizes
	GoVersion GoVersion
	Filename  string
	File      *ast.File
	FileSrc   []byte
}

// CheckerContext is a checker-specific context.
type CheckerContext struct {
	*Context
	Info     *CheckerInfo
	Params   map[string]interface{}
	warnings []Warning
}

// TypeOf returns the type of expression or nil.
func (c *CheckerContext) TypeOf(x ast.Expr) types.Type {
	return typeOf(c.TypesInfo, x)
}

func typeOf(info *types.Info, x ast.Expr) types.Type {
	if x == nil {
		return nil
	}
	if tv, ok := info.Types[x]; ok && tv.Type != nil {
		return tv.Type
	}
	if id, ok := x.(*ast.Ident); ok {
		if obj := info.ObjectOf(id); obj != nil {
			return obj.Type()
		}
	}
	return nil
}

// Warn adds a warning.
func (c *CheckerContext) Warn(node ast.Node, format string, args ...interface{}) {
	c.warnings = append(c.warnings, Warning{Pos: node.Pos(), Text: c.Sprintf(format, args...)})
}

// WarnPos adds a warning for a position.
func (c *CheckerContext) WarnPos(pos token.Pos, format string, args ...interface{}) {
	c.warnings = append(c.warnings, Warning{Pos: pos, Text: c.Sprintf(format, args...)})
}

// Sprintf formats with ast.Node args printed as Go source.
func (c *CheckerContext) Sprintf(format string, args ...interface{}) string {
	for i := range args {
		if n, ok := args[i].(ast.Node); ok {
			args[i] = nodeString(c.Fset, n)
		}
	}
	return fmt.Sprintf(format, args...)
}

// NodeString prints node.
func (c *CheckerContext) NodeString(n ast.Node) string {
	return nodeString(c.Fset, n)
}

func nodeString(fset *token.FileSet, n ast.Node) string {
	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, n); err != nil {
		return fmt.Sprintf("%v", n)
	}
	return buf.String()
}

// TakeWarnings returns and resets collected warnings.
func (c *CheckerContext) TakeWarnings() []Warning {
	w := c.warnings
	c.warnings = nil
	return w
}

// IntParam returns int param.
func (c *CheckerContext) IntParam(name string) int {
	v, _ := c.Params[name].(int)
	return v
}

// BoolParam returns bool param.
func (c *CheckerContext) BoolParam(name string) bool {
	v, _ := c.Params[name].(bool)
	return v
}

// StringParam returns string param.
func (c *CheckerContext) StringParam(name string) string {
	v, _ := c.Params[name].(string)
	return v
}

// FileWalker checks a single file.
type FileWalker interface {
	WalkFile(f *ast.File)
}

type constructor func(ctx *CheckerContext) (FileWalker, error)

var registry = map[string]constructor{}

func register(name string, ctor constructor) {
	if _, ok := registry[name]; ok {
		panic("duplicated checker: " + name)
	}
	registry[name] = ctor
}

// Checker is an instantiated checker.
type Checker struct {
	Info   *CheckerInfo
	Ctx    *CheckerContext
	walker FileWalker
}

// NewChecker creates a checker.
func NewChecker(base *Context, info *CheckerInfo, params map[string]interface{}) (*Checker, error) {
	ctx := &CheckerContext{Context: base, Info: info, Params: params}
	ctor := registry[info.Name]
	if ctor == nil {
		return &Checker{Info: info, Ctx: ctx}, nil
	}
	w, err := ctor(ctx)
	if err != nil {
		return nil, err
	}
	return &Checker{Info: info, Ctx: ctx, walker: w}, nil
}

// Check runs checker over a file.
func (c *Checker) Check(f *ast.File) (ws []Warning) {
	if c.walker == nil {
		return nil
	}
	defer func() {
		if r := recover(); r != nil {
			ws = c.Ctx.TakeWarnings()
		}
	}()
	c.walker.WalkFile(f)
	return c.Ctx.TakeWarnings()
}

// IsTestFile reports whether filename is a test file.
func IsTestFile(filename string) bool {
	return strings.HasSuffix(filename, "_test.go")
}
EOF
echo"}

