		}
		return nil, fmt.Errorf("go list: %v: %s", err, msg)
	}

	byID := map[string]*listPackage{}
	var roots []*listPackage
	dec := json.NewDecoder(&stdout)
	for {
		p := new(listPackage)
		if err := dec.Decode(p); err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
		if p.ImportPath == "" {
			if p.Error != nil {
				pos := p.Error.Pos
				if pos == "" {
