		}
		pkg.Syntax = append(pkg.Syntax, f)
		pkg.Sources = append(pkg.Sources, src)
	}

	lp := pkg.lp
	byID := pkg.byID
	lookup := func(path string) (io.ReadCloser, error) {
		id := path
		if lp.ImportMap != nil {
