package cli

import (
	"flag"
	"fmt"
	"go/build"
	"go/token"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"

	"github.com/gocritic-reimpl/gocritic/internal/lint"
	"github.com/gocritic-reimpl/gocritic/internal/loader"
)

type checkProgram struct {
	checkGenerated     bool
	checkTests         bool
	concurrency        int
	cpuprofile         string
	disable            string
	enable             string
	enableAll          bool
	exitCode           int
	goVersion          string
	memprofile         string
	shorterErrLocation bool
	verbose            bool

	params map[string]map[string]interface{}

	workDir string
	gopath  string
	goroot  string

	checkers []*lint.Checker
	base     *lint.Context
	found    bool
}

func defaultEnabled() string {
	var names []string
	for _, info := range lint.AllCheckers() {
		if info.HasTag("experimental") || info.HasTag("opinionated") || info.HasTag("performance") || info.HasTag("security") {
			continue
		}
		names = append(names, info.Name)
	}
	return strings.Join(names, ",")
}

func runCheck(args []string) error {
	p := &checkProgram{params: map[string]map[string]interface{}{}}
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)

	type paramRef struct {
		checker string
		name    string
		kind    string
		i       *int
		b       *bool
		s       *string
	}
	var refs []paramRef
	for _, info := range lint.AllCheckers() {
		for _, prm := range info.Params {
			key := "@" + info.Name + "." + prm.Name
			ref := paramRef{checker: info.Name, name: prm.Name, kind: prm.Type}
			switch prm.Type {
			case "int":
				v, _ := strconv.Atoi(prm.Default)
				ref.i = fs.Int(key, v, prm.Usage)
			case "bool":
				ref.b = fs.Bool(key, prm.Default == "true", prm.Usage)
			default:
				ref.s = fs.String(key, prm.Default, prm.Usage)
			}
			refs = append(refs, ref)
		}
	}

	fs.BoolVar(&p.checkGenerated, "checkGenerated", false, "whether to check generated files")
	fs.BoolVar(&p.checkTests, "checkTests", true, "whether to check test files")
	fs.IntVar(&p.concurrency, "concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	fs.StringVar(&p.cpuprofile, "cpuprofile", "", "write CPU profile to the specified file")
	fs.StringVar(&p.disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	fs.StringVar(&p.enable, "enable", defaultEnabled(), "comma-separated list of enabled checkers. Can include #tags")
	fs.BoolVar(&p.enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.IntVar(&p.exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
	fs.StringVar(&p.goVersion, "go", "", "select the Go version to target. Leave as string for the latest")
	fs.StringVar(&p.memprofile, "memprofile", "", "write memory profile to the specified file")
	fs.BoolVar(&p.shorterErrLocation, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.BoolVar(&p.verbose, "v", false, "whether to print output useful during linter debugging")

	if err := fs.Parse(args); err != nil {
		log.Fatalf("parse args: %v", err)
	}
	for _, ref := range refs {
		m := p.params[ref.checker]
		if m == nil {
			m = map[string]interface{}{}
			p.params[ref.checker] = m
		}
		switch ref.kind {
		case "int":
			m[ref.name] = *ref.i
		case "bool":
			m[ref.name] = *ref.b
		default:
			m[ref.name] = *ref.s
		}
	}

	patterns := fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}

	if wd, err := os.Getwd(); err == nil {
		p.workDir = wd
	}
	p.gopath = build.Default.GOPATH
	p.goroot = os.Getenv("GOROOT")

	fset := token.NewFileSet()
	pkgs, err := loader.Load(fset, patterns, p.checkTests)
	if err != nil {
		log.Fatalf("load packages: %v", err)
	}

	p.base = &lint.Context{Fset: fset}
	p.base.GoVersion = parseGoVersion(p.goVersion)

	if err := p.initCheckers(); err != nil {
		log.Fatalf("init checkers: %v", err)
	}

	pkgs = filterPackages(pkgs, p.checkTests)
	for _, pkg := range pkgs {
		if len(pkg.Files) == 0 {
			continue
		}
		pkg.Parse(fset)
		p.checkPackage(pkg)
	}

	if p.found {
		os.Exit(p.exitCode)
	}
	return nil
}

func parseGoVersion(s string) lint.GoVersion {
	s = strings.TrimPrefix(s, "go")
	if s == "" {
		return lint.GoVersion{}
	}
	parts := strings.Split(s, ".")
	if len(parts) != 2 {
		panic(fmt.Sprintf("invalid Go version format: %s", s))
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		panic(fmt.Sprintf("invalid major version part: %s: %s", parts[0], err))
	}
	minor, err := strconv.Atoi(parts[1])
	if err != nil {
		panic(fmt.Sprintf("invalid minor version part: %s: %s", parts[1], err))
	}
	return lint.GoVersion{Major: major, Minor: minor}
}

func filterPackages(pkgs []*loader.Package, tests bool) []*loader.Package {
	ids := map[string]bool{}
	for _, pkg := range pkgs {
		ids[pkg.ID] = true
	}
	var res []*loader.Package
	for _, pkg := range pkgs {
		if strings.HasSuffix(pkg.ID, ".test") && pkg.Name == "main" {
			continue
		}
		if tests && !strings.Contains(pkg.ID, " ") {
			if ids[pkg.ID+" ["+pkg.ID+".test]"] {
				continue
			}
		}
		res = append(res, pkg)
	}
	return res
}

func (p *checkProgram) initCheckers() error {
	enabledNames := map[string]bool{}
	enabledTags := map[string]bool{}
	for _, s := range strings.Split(p.enable, ",") {
		if strings.HasPrefix(s, "#") {
			enabledTags[s[1:]] = true
		} else {
			enabledNames[s] = true
		}
	}
	disabledNames := map[string]bool{}
	var disabledTags []string
	for _, s := range strings.Split(p.disable, ",") {
		if strings.HasPrefix(s, "#") {
			disabledTags = append(disabledTags, s[1:])
		} else {
			disabledNames[s] = true
		}
	}
	isDisabledTag := func(tag string) bool {
		for _, t := range disabledTags {
			if t == tag {
				return true
			}
		}
		return false
	}

	var enabled []*lint.CheckerInfo
outer:
