import (
	"go/ast"
	"go/token"
	"go/types"
	"reflect"
	"strings"
)

var (
	posType          = reflect.TypeOf(token.NoPos)
	objPtrType       = reflect.TypeOf((*ast.Object)(nil))
	scopePtrType     = reflect.TypeOf((*ast.Scope)(nil))
	commentGroupType = reflect.TypeOf((*ast.CommentGroup)(nil))
)

// astEqual reports whether two AST nodes are structurally equal.
func astEqual(x, y ast.Node) bool {
	if isNilNode(x) || isNilNode(y) {
		return isNilNode(x) && isNilNode(y)
	}
	return equalValue(reflect.ValueOf(x), reflect.ValueOf(y))
}

func isNilNode(n ast.Node) bool {
	if n == nil {
		return true
	}
	v := reflect.ValueOf(n)
	return v.Kind() == reflect.Ptr && v.IsNil()
}

func equalValue(x, y reflect.Value) bool {
	if x.Kind() == reflect.Interface {
		if x.IsNil() || y.IsNil() {
			return x.IsNil() && y.IsNil()
		}
		x = x.Elem()
		y = y.Elem()
	}
	if x.Type() != y.Type() {
		return false
	}
	switch x.Kind() {
	case reflect.Ptr:
		if x.IsNil() || y.IsNil() {
			return x.IsNil() && y.IsNil()
		}
		return equalValue(x.Elem(), y.Elem())
	case reflect.Struct:
		t := x.Type()
		for i := 0; i < t.NumField(); i++ {
			f := t.Field(i)
			switch f.Type {
			case objPtrType, scopePtrType, commentGroupType:
				continue
			case posType:
				if specialPosField(t, f.Name) {
					if (x.Field(i).Int() == 0) != (y.Field(i).Int() == 0) {
						return false
					}
				}
				continue
			}
			if !equalValue(x.Field(i), y.Field(i)) {
				return false
			}
		}
		return true
	case reflect.Slice:
		if x.Len() != y.Len() {
			return false
		}
		for i := 0; i < x.Len(); i++ {
			if !equalValue(x.Index(i), y.Index(i)) {
				return false
			}
		}
		return true
	case reflect.String:
		return x.String() == y.String()
	case reflect.Bool:
		return x.Bool() == y.Bool()
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return x.Int() == y.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return x.Uint() == y.Uint()
	default:
		return true
	}
}

func specialPosField(t reflect.Type, name string) bool {
	switch t {
	case reflect.TypeOf(ast.CallExpr{}):
		return name == "Ellipsis"
	case reflect.TypeOf(ast.TypeSpec{}):
		return name == "Assign"
	}
	return false
}

func unparen(x ast.Expr) ast.Expr {
	for {
		p, ok := x.(*ast.ParenExpr)
		if !ok {
			return x
		}
		x = p.X
	}
}

// qualifiedName returns "pkg.name" or "name" for simple selectors and identifiers.
func qualifiedName(x ast.Expr) string {
	switch x := x.(type) {
	case *ast.SelectorExpr:
		pkg, ok := x.X.(*ast.Ident)
		if !ok {
			return ""
		}
		return pkg.Name + "." + x.Sel.Name
	case *ast.Ident:
		return x.Name
	default:
		return ""
	}
}

func isSafeExpr(info *types.Info, expr ast.Expr) bool {
	switch expr := expr.(type) {
	case *ast.StarExpr:
		return isSafeExpr(info, expr.X)
	case *ast.BinaryExpr:
		return isSafeExpr(info, expr.X) && isSafeExpr(info, expr.Y)
	case *ast.UnaryExpr:
		return expr.Op != token.ARROW && isSafeExpr(info, expr.X)
	case *ast.BasicLit, *ast.Ident:
		return true
	case *ast.IndexExpr:
		return isSafeExpr(info, expr.X) && isSafeExpr(info, expr.Index)
	case *ast.SelectorExpr:
		return isSafeExpr(info, expr.X)
	case *ast.ParenExpr:
		return isSafeExpr(info, expr.X)
	case *ast.CompositeLit:
		return isSafeExprList(info, expr.Elts)
	case *ast.CallExpr:
		tv := info.Types[expr.Fun]
		return tv.IsType() && isSafeExprList(info, expr.Args)
	default:
		return false
	}
}

func isSafeExprList(info *types.Info, list []ast.Expr) bool {
	for _, e := range list {
		if !isSafeExpr(info, e) {
			return false
		}
	}
	return true
}

func isBlank(x ast.Expr) bool {
	id, ok := x.(*ast.Ident)
	return ok && id.Name == "_"
}

func isTestFuncName(name string) bool {
	return strings.HasPrefix(name, "Test") || strings.HasPrefix(name, "Benchmark")
}

// walkFuncBodies calls fn for every top-level function declaration with a body.
func walkFuncDecls(f *ast.File, fn func(decl *ast.FuncDecl)) {
	for _, decl := range f.Decls {
