package lint

import (
	"bytes"
	"go/ast"
	"go/constant"
	"go/printer"
	"go/token"
	"go/types"
	"sort"
	"strings"
)

// rgRunner emulates the reporting behavior of rule-based checkers:
// all reports are collected and then sorted by their message.
type rgRunner struct {
	ctx     *CheckerContext
	reports []rgReport
}

type rgReport struct {
	pos token.Pos
	msg string
}

func newRG(ctx *CheckerContext) *rgRunner {
	return &rgRunner{ctx: ctx}
}

func (r *rgRunner) text(n ast.Node) string {
	return nodeSrcText(r.ctx, n)
}

// nodeSrcText returns source text of the node.
func nodeSrcText(ctx *CheckerContext, n ast.Node) string {
	if n == nil {
		return ""
	}
	tf := ctx.Fset.File(n.Pos())
	src := ctx.FileSrc
	if tf != nil && src != nil && n.Pos().IsValid() && n.End().IsValid() {
		from := tf.Offset(n.Pos())
		to := int(n.End()) - tf.Base()
		if from >= 0 && from < len(src) && to >= 0 && to < len(src) {
			return string(src[from:to])
		}
	}
	if c, ok := n.(*ast.Comment); ok {
		return c.Text
	}
	var buf bytes.Buffer
	printer.Fprint(&buf, ctx.Fset, n)
	return buf.String()
}

// srcRange returns source text between two positions.
func srcRange(ctx *CheckerContext, from, to token.Pos) string {
	tf := ctx.Fset.File(from)
	src := ctx.FileSrc
	if tf == nil {
		return ""
	}
	a := int(from) - tf.Base()
	b := int(to) - tf.Base()
	if a >= 0 && b <= len(src) && a <= b {
		return string(src[a:b])
	}
	return ""
}

func (r *rgRunner) report(n ast.Node, msg string) {
	r.reports = append(r.reports, rgReport{pos: n.Pos(), msg: msg})
}

func (r *rgRunner) reportPos(pos token.Pos, msg string) {
	r.reports = append(r.reports, rgReport{pos: pos, msg: msg})
}

func (r *rgRunner) flush() {
	reports := r.reports
	sort.Slice(reports, func(i, j int) bool {
		return reports[i].msg < reports[j].msg
	})
	for _, rep := range reports {
		r.ctx.warnings = append(r.ctx.warnings, Warning{Pos: rep.pos, Text: rep.msg})
	}
	r.reports = nil
}

// interp replaces $name occurrences in tmpl using vars.
// "$$" is replaced with the whole match text.
func interp(tmpl string, vars map[string]string) string {
	var b strings.Builder
	for i := 0; i < len(tmpl); i++ {
		ch := tmpl[i]
		if ch != '$' {
			b.WriteByte(ch)
			continue
		}
		if i+1 < len(tmpl) && tmpl[i+1] == '$' {
			b.WriteString(vars["$"])
			i++
			continue
		}
		j := i + 1
		for j < len(tmpl) && isIdentChar(tmpl[j]) {
			j++
		}
		name := tmpl[i+1 : j]
		if v, ok := vars[name]; ok && name != "" {
			b.WriteString(v)
			i = j - 1
			continue
		}
		b.WriteByte(ch)
	}
	return b.String()
}

func isIdentChar(ch byte) bool {
	return ch == '_' || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9')
}

// walkAll visits every node in the file in pre-order.
func walkAll(f *ast.File, fn func(n ast.Node)) {
	ast.Inspect(f, func(n ast.Node) bool {
		if n != nil {
			fn(n)
		}
		return true
	})
}

// isPkgSel reports whether x is pkgPath.name selector (type-based).
func isPkgSel(info *types.Info, x ast.Expr, pkgPath, name string) bool {
	sel, ok := x.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != name {
		return false
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return false
	}
	pn, ok := info.ObjectOf(id).(*types.PkgName)
	return ok && pn.Imported().Path() == pkgPath
}

// pkgSelName returns the selector name if x is a selector from pkgPath.
func pkgSelName(info *types.Info, x ast.Expr, pkgPath string) string {
	sel, ok := x.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	pn, ok := info.ObjectOf(id).(*types.PkgName)
	if !ok || pn.Imported().Path() != pkgPath {
		return ""
	}
	return sel.Sel.Name
}

func isConst(info *types.Info, x ast.Expr) bool {
	tv, ok := info.Types[x]
	return ok && tv.Value != nil
}

func constValue(info *types.Info, x ast.Expr) constant.Value {
	tv, ok := info.Types[x]
	if !ok {
		return nil
	}
	return tv.Value
}

func isConstSlice(info *types.Info, x ast.Expr) bool {
	switch x := x.(type) {
	case *ast.CallExpr:
		if len(x.Args) != 1 {
			return false
		}
		lit, ok := x.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return false
		}
		typ, ok := typeOf(info, x.Fun).(*types.Slice)
		if !ok {
			return false
		}
		b, ok := typ.Elem().(*types.Basic)
		return ok && b.Kind() == types.Uint8
	case *ast.CompositeLit:
		typ, ok := typeOf(info, x).(*types.Slice)
		if !ok {
			return false
		}
		b, ok := typ.Elem().(*types.Basic)
		if !ok || b.Kind() != types.Uint8 {
			return false
		}
		for _, elt := range x.Elts {
			if !isConst(info, elt) {
				return false
			}
