package lint

import (
	"go/ast"
	"go/constant"
	"go/token"
	"go/types"
)

func init() {
	register("badCond", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkFuncDecls(f, func(decl *ast.FuncDecl) {
				if decl.Body == nil {
					return
				}
				ast.Inspect(decl.Body, func(n ast.Node) bool {
					switch n := n.(type) {
					case *ast.ForStmt:
						badCondCheckFor(ctx, n)
					case ast.Expr:
						badCondCheckExpr(ctx, n)
					}
					return true
				})
			})
		}), nil
	})
}

func badCondCheckExpr(ctx *CheckerContext, expr ast.Expr) {
	cond, ok := expr.(*ast.BinaryExpr)
	if !ok || cond.Op != token.LAND {
		return
	}
	lhs, ok1 := unparen(cond.X).(*ast.BinaryExpr)
	rhs, ok2 := unparen(cond.Y).(*ast.BinaryExpr)
	if !ok1 || !ok2 {
		return
	}
	if lhs.Op == token.LSS && rhs.Op == token.GTR && astEqual(lhs.X, rhs.X) {
		a := ctx.TypesInfo.Types[lhs.Y].Value
		b := ctx.TypesInfo.Types[rhs.Y].Value
		if a != nil && b != nil && constCompare(a, token.LSS, b) {
			ctx.Warn(cond, "`%s` condition is always false", cond)
			return
		}
	}
	if lhs.Op == token.EQL && rhs.Op == token.EQL && astEqual(lhs.X, rhs.X) {
		ctx.Warn(cond, "`%s` condition is suspicious", cond)
	}
}

func constCompare(a constant.Value, op token.Token, b constant.Value) (res bool) {
	defer func() {
		if recover() != nil {
			res = false
		}
	}()
	return constant.Compare(a, op, b)
}

func badCondCheckFor(ctx *CheckerContext, stmt *ast.ForStmt) {
	init, ok := stmt.Init.(*ast.AssignStmt)
	if !ok || init.Tok != token.DEFINE || len(init.Lhs) != 1 || len(init.Rhs) != 1 {
		return
	}
	if lit, ok := init.Rhs[0].(*ast.BasicLit); !ok || lit.Value != "0" {
		return
	}
	iter, ok := init.Lhs[0].(*ast.Ident)
	if !ok {
		return
	}
	cond, ok := stmt.Cond.(*ast.BinaryExpr)
	if !ok {
		return
	}
	var i, n ast.Expr
	var op token.Token
	switch cond.Op {
	case token.GTR:
		i, n, op = cond.X, cond.Y, token.LSS
	case token.LSS:
		i, n, op = cond.Y, cond.X, token.GTR
	default:
		return
	}
	if !astEqual(iter, i) || !sideEffectFree(ctx.TypesInfo, n) {
		return
	}
	post, ok := stmt.Post.(*ast.IncDecStmt)
	if !ok || post.Tok != token.INC {
		return
	}
	suggest := *cond
	suggest.Op = op
	ctx.Warn(stmt, "`%s` in loop; probably meant `%s`?", cond, &suggest)
}

// sideEffectFree reports whether expr is softly side-effect free.
func sideEffectFree(info *types.Info, expr ast.Expr) bool {
	if expr == nil {
		return true
	}
	switch expr := expr.(type) {
	case *ast.Ident, *ast.BasicLit, *ast.BadExpr, *ast.FuncLit:
		return true
	case *ast.ParenExpr:
		return sideEffectFree(info, expr.X)
	case *ast.SelectorExpr:
		return sideEffectFree(info, expr.X)
	case *ast.StarExpr:
		return sideEffectFree(info, expr.X)
	case *ast.UnaryExpr:
		return expr.Op != token.ARROW && sideEffectFree(info, expr.X)
	case *ast.BinaryExpr:
		return sideEffectFree(info, expr.X) && sideEffectFree(info, expr.Y)
	case *ast.IndexExpr:
		return sideEffectFree(info, expr.X) && sideEffectFree(info, expr.Index)
	case *ast.IndexListExpr:
		if !sideEffectFree(info, expr.X) {
			return false
		}
		for _, x := range expr.Indices {
			if !sideEffectFree(info, x) {
				return false
			}
		}
		return true
	case *ast.SliceExpr:
		return sideEffectFree(info, expr.X) && sideEffectFree(info, expr.Low) &&
			sideEffectFree(info, expr.High) && sideEffectFree(info, expr.Max)
	case *ast.TypeAssertExpr:
		return sideEffectFree(info, expr.X)
	case *ast.KeyValueExpr:
		return sideEffectFree(info, expr.Key) && sideEffectFree(info, expr.Value)
	case *ast.CompositeLit:
		for _, elt := range expr.Elts {
			if !sideEffectFree(info, elt) {
				return false
			}
		}
		return true
	case *ast.CallExpr:
		if isTypeExpr(info, expr.Fun) {
			for _, arg := range expr.Args {
				if !sideEffectFree(info, arg) {
					return false
				}
			}
			return true
		}
		return false
	case *ast.ArrayType, *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.StructType, *ast.InterfaceType, *ast.Ellipsis:
		return true
	default:
		return false
	}
}

func isTypeExpr(info *types.Info, x ast.Expr) bool {
	switch x := x.(type) {
	case *ast.StarExpr:
		return isTypeExpr(info, x.X)
	case *ast.ParenExpr:
		return isTypeExpr(info, x.X)
	case *ast.SelectorExpr:
		tv, ok := info.Types[x]
		return ok && tv.IsType()
	case *ast.Ident:
		_, ok := info.ObjectOf(x).(*types.TypeName)
		return ok
	case *ast.ArrayType, *ast.MapType, *ast.ChanType, *ast.FuncType, *ast.StructType, *ast.InterfaceType:
		return true
	default:
		tv, ok := info.Types[x]
		return ok && tv.IsType()
	}
}
