// walkStmtListsAll visits every statement list (block, case, comm clause) in the file, pre-order.
func walkStmtListsAll(f *ast.File, fn func(list []ast.Stmt)) {
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.BlockStmt:
			fn(n.List)
		case *ast.CaseClause:
			fn(n.Body)
		case *ast.CommClause:
			fn(n.Body)
		}
		return true
	})
}

// matchMethodCallStmt matches `$x.name()` expression statement and returns $x.
func matchMethodCallStmt(stmt ast.Stmt, name string) ast.Expr {
	es, ok := stmt.(*ast.ExprStmt)
	if !ok {
		return nil
	}
	return matchMethodCall(es.X, name, 0)
}

// matchMethodCall matches `$x.name(args...)` with exact args count and returns $x.
func matchMethodCall(x ast.Expr, name string, nargs int) ast.Expr {
	call, ok := x.(*ast.CallExpr)
	if !ok || len(call.Args) != nargs || call.Ellipsis.IsValid() {
		return nil
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != name {
		return nil
	}
	return sel.X
}
