package lint

import (
	"go/ast"
)

func init() {
	register("badLock", func(ctx *CheckerContext) (FileWalker, error) {
		type rule struct {
			lock, unlock string
			deferred     bool
			msg          string
		}
		rules := []rule{
			{"Lock", "Unlock", false, "defer is missing, mutex is unlocked immediately"},
			{"RLock", "RUnlock", false, "defer is missing, mutex is unlocked immediately"},
			{"Lock", "RUnlock", true, "suspicious unlock, maybe Unlock was intended?"},
			{"RLock", "Unlock", true, "suspicious unlock, maybe RUnlock was intended?"},
		}
		return walkerFunc(func(f *ast.File) {
			rg := newRG(ctx)
			walkStmtListsAll(f, func(list []ast.Stmt) {
				for _, r := range rules {
					for i := 0; i+1 < len(list); i++ {
						mu1 := matchMethodCallStmt(list[i], r.lock)
						if mu1 == nil {
							continue
						}
						var mu2 ast.Expr
						if r.deferred {
							d, ok := list[i+1].(*ast.DeferStmt)
							if !ok {
								continue
							}
							mu2 = matchMethodCall(d.Call, r.unlock, 0)
						} else {
							mu2 = matchMethodCallStmt(list[i+1], r.unlock)
						}
						if mu2 == nil || rg.text(mu1) != rg.text(mu2) {
							continue
						}
						rg.report(mu2, r.msg)
						i++
					}
				}
			})
			rg.flush()
		}), nil
	})
}
