import (
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	register("badSorting", func(ctx *CheckerContext) (FileWalker, error) {
		type rule struct {
			fn   string
			elem types.BasicKind
			msg  string
		}
		rules := []rule{
			{"IntSlice", types.Int, "suspicious sort.IntSlice usage, maybe sort.Ints was intended?"},
			{"Float64Slice", types.Float64, "suspicious sort.Float64s usage, maybe sort.Float64s was intended?"},
			{"StringSlice", types.String, "suspicious sort.StringSlice usage, maybe sort.Strings was intended?"},
		}
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				assign, ok := n.(*ast.AssignStmt)
				if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
					return
				}
				call, ok := assign.Rhs[0].(*ast.CallExpr)
				if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() {
					return
				}
				x := assign.Lhs[0]
				if !astEqual(x, call.Args[0]) {
					return
				}
				for _, r := range rules {
					if !isPkgSel(info, call.Fun, "sort", r.fn) {
						continue
					}
					if isSliceOfBasic(ctx.TypeOf(x), r.elem) {
						rg.report(assign, r.msg)
					}
					break
				}
			})
			rg.flush()
		}), nil
	})
}

