package lint

import (
	"go/ast"
)

func init() {
	register("badSyncOnceFunc", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			if !ctx.GoVersion.GreaterOrEqual(GoVersion{1, 21}) {
				return
			}
			info := ctx.TypesInfo
			rg := newRG(ctx)
			matchOnce := func(x ast.Expr) ast.Expr {
				call, ok := x.(*ast.CallExpr)
				if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, "sync", "OnceFunc") {
					return nil
				}
				return call.Args[0]
			}
			ast.Inspect(f, func(n ast.Node) bool {
				var list []ast.Stmt
				isList := false
				switch n := n.(type) {
				case *ast.BlockStmt:
					list, isList = n.List, true
				case *ast.CaseClause:
					list, isList = n.Body, true
				case *ast.CommClause:
					list, isList = n.Body, true
				case *ast.CallExpr:
					if len(n.Args) == 0 && !n.Ellipsis.IsValid() {
						if x := matchOnce(n.Fun); x != nil {
							rg.report(n, "possible sync.OnceFunc misuse, consider to assign sync.OnceFunc("+rg.text(x)+") to a variable")
						}
					}
				}
				if isList {
					for _, stmt := range list {
						es, ok := stmt.(*ast.ExprStmt)
						if !ok {
							continue
						}
						if x := matchOnce(es.X); x != nil {
							rg.report(list[0], "possible sync.OnceFunc misuse, sync.OnceFunc("+rg.text(x)+") result is not used")
							break
						}
					}
				}
				return true
			})
			rg.flush()
		}), nil
	})
}
