		return nil
	}
	return copyNode(x).(ast.Expr)
}

// copyNode returns a deep copy of an AST node.
func copyNode(n ast.Node) ast.Node {
	if isNilNode(n) {
		return n
	}
	v := deepCopyValue(reflect.ValueOf(n))
	return v.Interface().(ast.Node)
}

func deepCopyValue(v reflect.Value) reflect.Value {
	switch v.Kind() {
	case reflect.Ptr:
		if v.IsNil() {
			return v
		}
		switch v.Type() {
		case objPtrType, scopePtrType:
			return v
		}
		nv := reflect.New(v.Type().Elem())
		nv.Elem().Set(deepCopyValue(v.Elem()))
		return nv
	case reflect.Interface:
		if v.IsNil() {
			return v
		}
		c := deepCopyValue(v.Elem())
		nv := reflect.New(v.Type()).Elem()
		nv.Set(c)
		return nv
	case reflect.Struct:
		nv := reflect.New(v.Type()).Elem()
		for i := 0; i < v.NumField(); i++ {
			if !nv.Field(i).CanSet() {
				continue
			}
			nv.Field(i).Set(deepCopyValue(v.Field(i)))
		}
		return nv
	case reflect.Slice:
		if v.IsNil() {
			return v
		}
		nv := reflect.MakeSlice(v.Type(), v.Len(), v.Len())
		for i := 0; i < v.Len(); i++ {
			nv.Index(i).Set(deepCopyValue(v.Index(i)))
		}
		return nv
	default:
		return v
	}
}

// applyPost rewrites expression tree in post-order.
// The post function returns a replacement for the node (or the node itself).
func applyPost(x ast.Expr, post func(x ast.Expr) ast.Expr) ast.Expr {
	if x == nil {
		return nil
	}
	switch n := x.(type) {
	case *ast.BinaryExpr:
		n.X = applyPost(n.X, post)
		n.Y = applyPost(n.Y, post)
	case *ast.UnaryExpr:
		n.X = applyPost(n.X, post)
	case *ast.ParenExpr:
		n.X = applyPost(n.X, post)
	case *ast.StarExpr:
		n.X = applyPost(n.X, post)
	case *ast.SelectorExpr:
		n.X = applyPost(n.X, post)
		n.Sel = applyPost(n.Sel, post).(*ast.Ident)
	case *ast.CallExpr:
		n.Fun = applyPost(n.Fun, post)
		for i := range n.Args {
			n.Args[i] = applyPost(n.Args[i], post)
		}
	case *ast.IndexExpr:
		n.X = applyPost(n.X, post)
		n.Index = applyPost(n.Index, post)
	case *ast.IndexListExpr:
		n.X = applyPost(n.X, post)
		for i := range n.Indices {
			n.Indices[i] = applyPost(n.Indices[i], post)
		}
	case *ast.SliceExpr:
		n.X = applyPost(n.X, post)
		n.Low = applyPost(n.Low, post)
		n.High = applyPost(n.High, post)
		n.Max = applyPost(n.Max, post)
	case *ast.TypeAssertExpr:
		n.X = applyPost(n.X, post)
		n.Type = applyPost(n.Type, post)
	case *ast.CompositeLit:
		n.Type = applyPost(n.Type, post)
		for i := range n.Elts {
			n.Elts[i] = applyPost(n.Elts[i], post)
		}
	case *ast.KeyValueExpr:
		n.Key = applyPost(n.Key, post)
		n.Value = applyPost(n.Value, post)
	}
	return post(x)
}
