package lint

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strconv"
)

func init() {
	register("boolExprSimplify", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				switch x.(type) {
				case *ast.BinaryExpr, *ast.UnaryExpr:
				default:
					return true
				}
				typ := ctx.TypeOf(x)
				if typ == nil || !hasBoolKind(typ.Underlying()) {
					return true
				}
				s := &boolSimplifier{info: ctx.TypesInfo}
				s.hasFloats = exprHasFloats(ctx, x)
				y := s.simplify(copyExpr(x))
				if !astEqual(x, y) {
					ctx.Warn(x, "can simplify `%s` to `%s`", x, y)
					return false
				}
				return true
			})
		}), nil
	})
}

func hasBoolKind(typ types.Type) bool {
	b, ok := typ.(*types.Basic)
	return ok && (b.Kind() == types.Bool || b.Kind() == types.UntypedBool)
}

func exprHasFloats(ctx *CheckerContext, x ast.Expr) bool {
	has := false
	ast.Inspect(x, func(n ast.Node) bool {
		if e, ok := n.(ast.Expr); ok {
			typ := ctx.TypeOf(e)
			if typ == nil {
				return true
			}
			if b, ok := typ.Underlying().(*types.Basic); ok && b.Info()&types.IsFloat != 0 {
				has = true
				return false
			}
		}
		return true
	})
	return has
}

type boolSimplifier struct {
	info      *types.Info
	hasFloats bool
}

func (s *boolSimplifier) simplify(x ast.Expr) ast.Expr {
	return applyPost(x, func(n ast.Expr) ast.Expr {
		if r, ok := s.doubleNegation(n); ok {
			return r
		}
		if r, ok := s.negatedEquals(n); ok {
			return r
		}
		if r, ok := s.invertComparison(n); ok {
			return r
		}
		if r, ok := s.combineChecks(n); ok {
			return r
		}
		if r, ok := s.removeIncDec(n); ok {
			return r
		}
		if r, ok := s.foldRanges(n); ok {
			return r
		}
		return n
	})
}

func toUnary(x ast.Expr) *ast.UnaryExpr {
	if u, ok := x.(*ast.UnaryExpr); ok {
		return u
	}
	return &ast.UnaryExpr{}
}

func toBinary(x ast.Expr) *ast.BinaryExpr {
	if b, ok := x.(*ast.BinaryExpr); ok {
		return b
	}
	return &ast.BinaryExpr{}
}

func toBasicLit(x ast.Expr) *ast.BasicLit {
	if b, ok := x.(*ast.BasicLit); ok {
		return b
	}
	return &ast.BasicLit{}
}

func (s *boolSimplifier) doubleNegation(n ast.Expr) (ast.Expr, bool) {
	neg1 := toUnary(n)
	neg2 := toUnary(unparen(neg1.X))
	if neg1.Op == token.NOT && neg2.Op == token.NOT {
		return unparen(neg2.X), true
	}
	return nil, false
}

func (s *boolSimplifier) negatedEquals(n ast.Expr) (ast.Expr, bool) {
	x, ok := n.(*ast.BinaryExpr)
	if !ok || x.Op != token.EQL {
		return nil, false
	}
	neg1 := toUnary(x.X)
	neg2 := toUnary(x.Y)
	if neg1.Op == token.NOT && neg2.Op == token.NOT {
		x.X = neg1.X
		x.Y = neg2.X
		return x, true
	}
	return nil, false
}

func (s *boolSimplifier) invertComparison(n ast.Expr) (ast.Expr, bool) {
	if s.hasFloats {
		return nil, false
	}
	neg := toUnary(n)
	cmp := toBinary(unparen(neg.X))
	if neg.Op != token.NOT {
		return nil, false
	}
	switch cmp.Op {
	case token.EQL:
		cmp.Op = token.NEQ
	case token.NEQ:
		cmp.Op = token.EQL
	case token.LSS:
		cmp.Op = token.GEQ
	case token.GTR:
		cmp.Op = token.LEQ
	case token.LEQ:
		cmp.Op = token.GTR
	case token.GEQ:
		cmp.Op = token.LSS
	default:
		return nil, false
	}
	return cmp, true
}

func (s *boolSimplifier) isSafe(x ast.Expr) bool {
	return sideEffectFree(s.info, x)
}

func (s *boolSimplifier) combineChecks(n ast.Expr) (ast.Expr, bool) {
	or, ok := n.(*ast.BinaryExpr)
	if !ok || or.Op != token.LOR {
		return nil, false
	}
	lhs := toBinary(unparen(or.X))
	rhs := toBinary(unparen(or.Y))
	if !astEqual(lhs.X, rhs.X) || !astEqual(lhs.Y, rhs.Y) {
		return nil, false
	}
	if !s.isSafe(lhs.X) || !s.isSafe(lhs.Y) {
		return nil, false
	}
	table := []struct{ x, y, res token.Token }{
		{token.GTR, token.EQL, token.GEQ},
		{token.EQL, token.GTR, token.GEQ},
		{token.LSS, token.EQL, token.LEQ},
		{token.EQL, token.LSS, token.LEQ},
	}
	for _, comb := range table {
		if comb.x == lhs.Op && comb.y == rhs.Op {
			return &ast.BinaryExpr{Op: comb.res, X: lhs.X, Y: lhs.Y}, true
		}
	}
	return nil, false
}

func (s *boolSimplifier) removeIncDec(n ast.Expr) (ast.Expr, bool) {
	cmp := toBinary(n)
	matchOneWay := func(op token.Token, x, y *ast.BinaryExpr) bool {
		if x.Op != op || toBasicLit(x.Y).Value != "1" {
			return false
		}
		if y.Op == op && toBasicLit(y.Y).Value == "1" {
			return false
		}
		return true
	}
	replace := func(lhsOp, rhsOp, repl token.Token) (ast.Expr, bool) {
		lhs := toBinary(cmp.X)
		rhs := toBinary(cmp.Y)
		switch {
		case matchOneWay(lhsOp, lhs, rhs):
			cmp.X = lhs.X
			cmp.Op = repl
			return cmp, true
		case matchOneWay(rhsOp, rhs, lhs):
			cmp.Y = rhs.X
			cmp.Op = repl
			return cmp, true
		default:
			return nil, false
		}
	}
	switch cmp.Op {
	case token.GTR:
		return replace(token.ADD, token.SUB, token.GEQ)
	case token.GEQ:
		return replace(token.SUB, token.ADD, token.GTR)
	case token.LSS:
		return replace(token.SUB, token.ADD, token.LEQ)
	case token.LEQ:
		return replace(token.ADD, token.SUB, token.LSS)
	}
	return nil, false
}

func (s *boolSimplifier) foldRanges(n ast.Expr) (ast.Expr, bool) {
	if s.hasFloats {
		return nil, false
	}
	e, ok := n.(*ast.BinaryExpr)
	if !ok {
		return nil, false
	}
	lhs := toBinary(e.X)
	rhs := toBinary(e.Y)
	if !s.isSafe(lhs.X) || !s.isSafe(rhs.X) {
		return nil, false
	}
	if !astEqual(lhs.X, rhs.X) {
		return nil, false
	}
	c1, ok := int64Lit(lhs.Y)
	if !ok {
		return nil, false
	}
	c2, ok := int64Lit(rhs.Y)
	if !ok {
		return nil, false
	}
	type comb struct {
		lhsOp, rhsOp      token.Token
		rhsDiff, resDelta int64
	}
	try := func(table []comb, op token.Token) (ast.Expr, bool) {
		for _, c := range table {
			if lhs.Op != c.lhsOp || rhs.Op != c.rhsOp || c2-c1 != c.rhsDiff {
				continue
			}
			lhs.Op = op
			lhs.Y.(*ast.BasicLit).Value = fmt.Sprint(c1 + c.resDelta)
			return lhs, true
		}
		return nil, false
	}
	switch e.Op {
	case token.LAND:
		return try([]comb{
			{token.GTR, token.LSS, 2, 1},
			{token.GEQ, token.LSS, 1, 0},
			{token.GTR, token.LEQ, 1, 1},
			{token.GEQ, token.LEQ, 0, 0},
		}, token.EQL)
	case token.LOR:
		return try([]comb{
			{token.LSS, token.GTR, 0, 0},
			{token.LEQ, token.GTR, 1, 1},
			{token.LSS, token.GEQ, 1, 0},
			{token.LEQ, token.GEQ, 2, 1},
		}, token.NEQ)
	}
	return nil, false
}

func int64Lit(x ast.Expr) (int64, bool) {
	lit, ok := x.(*ast.BasicLit)
	if !ok {
		return 0, false
	}
	v, err := strconv.ParseInt(lit.Value, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}
