package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

type nameKind int

const (
	nameVar nameKind = iota
	nameConst
	nameParam
)

type localName struct {
	ID   *ast.Ident
	Kind nameKind
}

// walkLocalDefs emulates the local definitions walker.
func walkLocalDefs(ctx *CheckerContext, f *ast.File, visit func(name localName, init ast.Expr)) {
	for _, decl := range f.Decls {
		decl, ok := decl.(*ast.FuncDecl)
		if !ok || decl.Body == nil {
			continue
		}
		walkLocalDefsFunc(ctx, decl, visit)
	}
}

func walkLocalDefsFunc(ctx *CheckerContext, decl *ast.FuncDecl, visit func(name localName, init ast.Expr)) {
	for _, p := range decl.Type.Params.List {
		for _, id := range p.Names {
			visit(localName{ID: id, Kind: nameParam}, nil)
		}
	}
	if decl.Type.Results != nil {
		for _, p := range decl.Type.Results.List {
			for _, id := range p.Names {
				visit(localName{ID: id, Kind: nameParam}, nil)
			}
		}
	}
	if decl.Recv != nil {
		for _, p := range decl.Recv.List {
			for _, id := range p.Names {
				visit(localName{ID: id, Kind: nameParam}, nil)
			}
		}
	}
	ast.Inspect(decl.Body, func(x ast.Node) bool {
		switch x := x.(type) {
		case *ast.AssignStmt:
			if x.Tok != token.DEFINE {
				return false
			}
			if len(x.Lhs) != len(x.Rhs) {
				for _, lhs := range x.Lhs {
					id, ok := lhs.(*ast.Ident)
					if !ok || ctx.TypesInfo.Defs[id] == nil {
						continue
					}
					visit(localName{ID: id, Kind: nameVar}, nil)
				}
			} else {
				for i, lhs := range x.Lhs {
					id, ok := lhs.(*ast.Ident)
					if !ok || ctx.TypesInfo.Defs[id] == nil {
						continue
					}
					visit(localName{ID: id, Kind: nameVar}, x.Rhs[i])
				}
			}
			return false
		case *ast.GenDecl:
			for _, spec := range x.Specs {
				spec, ok := spec.(*ast.ValueSpec)
				if !ok {
					return false
				}
				switch {
				case len(spec.Values) == 0:
					for _, id := range spec.Names {
						visit(localName{ID: id, Kind: nameVar}, nil)
					}
				case len(spec.Names) != len(spec.Values):
					for _, id := range spec.Names {
						visit(localName{ID: id, Kind: nameVar}, nil)
					}
				default:
					kind := nameVar
					if x.Tok == token.CONST {
						kind = nameConst
					}
					for i, id := range spec.Names {
						visit(localName{ID: id, Kind: kind}, spec.Values[i])
					}
				}
			}
			return false
		}
		return true
	})
}

func isBuiltinName(name string) bool {
	return types.Universe.Lookup(name) != nil
}
