package lint

import (
	"go/ast"
	"go/types"
)

func init() {
	register("caseOrder", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				s, ok := stmt.(*ast.TypeSwitchStmt)
				if !ok {
					return
				}
				caseOrderCheck(ctx, s)
			})
		}), nil
	})
}

func caseOrderCheck(ctx *CheckerContext, s *ast.TypeSwitchStmt) {
	type caseInfo struct {
		expr ast.Expr
		typ  types.Type
	}
	var cases []caseInfo
	for _, cc := range s.Body.List {
		clause, ok := cc.(*ast.CaseClause)
		if !ok {
			continue
		}
		for _, x := range clause.List {
			typ := ctx.TypeOf(x)
			if typ == nil || typ == types.Typ[types.Invalid] {
				ctx.Warn(clause, "type is not defined %s", x)
				return
			}
			for _, prev := range cases {
				iface, ok := prev.typ.Underlying().(*types.Interface)
				if ok && safeImplements(typ, iface) {
					ctx.Warn(clause, "case %s must go before the %s case", x, prev.expr)
					break
				}
			}
			cases = append(cases, caseInfo{expr: x, typ: typ})
		}
	}
}

func safeImplements(typ types.Type, iface *types.Interface) (res bool) {
	defer func() {
		if recover() != nil {
			res = false
		}
	}()
	return types.Implements(typ, iface)
}
