import (
	"go/ast"
	"regexp"
	"strings"
)

func init() {
	register("codegenComment", func(ctx *CheckerContext) (FileWalker, error) {
		patterns := []string{
			"this (?:file|code) (?:was|is) auto(?:matically)? generated",
			"this (?:file|code) (?:was|is) generated automatically",
			"this (?:file|code) (?:was|is) generated by",
			"this (?:file|code) (?:was|is) (?:auto(?:matically)? )?generated",
			"this (?:file|code) (?:was|is) generated",
			"code in this file (?:was|is) auto(?:matically)? generated",
			"generated (?:file|code) - do not edit",
		}
		re := regexp.MustCompile(`(?i)` + strings.Join(patterns, "|"))
		return walkerFunc(func(f *ast.File) {
			if f.Doc == nil {
				return
			}
			for _, c := range f.Doc.List {
				if re.MatchString(c.Text) {
					ctx.Warn(c, "comment should match `Code generated .* DO NOT EDIT.` regexp")
					return
				}
			}
		}), nil
	})
}
