			walkLocalComments(f, func(fn *ast.FuncDecl, cg *ast.CommentGroup) {
				s := cg.Text()
				for _, m := range []string{"TODO", "http://", "https://", "e.g. "} {
					if strings.Contains(s, m) {
						return
					}
				}
				if len(s) < minLength &&
					!strings.Contains(s, "print") &&
					!strings.Contains(s, "fmt.") &&
					!strings.Contains(s, "log.") {
					return
				}
				if notQuiteFuncCall.MatchString(s) {
					return
				}
				if strings.HasPrefix(fn.Name.Name, "Example") &&
					(strings.Contains(s, "Output:") || strings.Contains(s, "Unordered output:")) {
					return
				}
				stmt := parseStmtString(s)
				if stmt == nil {
					return
				}
				if !commentedOutCodePermittedStmt(stmt) {
					ctx.Warn(cg, "may want to remove commented-out code")
				}
			})
		}), nil
	})
}

// walkLocalComments visits comment groups inside function bodies.
func walkLocalComments(f *ast.File, fn func(decl *ast.FuncDecl, cg *ast.CommentGroup)) {
	for _, decl := range f.Decls {
		decl, ok := decl.(*ast.FuncDecl)
		if !ok || decl.Body == nil {
			continue
		}
		for _, cg := range f.Comments {
			if cg.Pos() > decl.Body.Pos() && cg.End() < decl.Body.End() {
				fn(decl, cg)
			}
		}
	}
}

// parseStmtString parses s as a statement; returns nil on failure.
func parseStmtString(s string) ast.Stmt {
	node, err := parser.ParseFile(token.NewFileSet(), "", "package main;func main() {"+s+"}", 0)
	if err != nil {
		return nil
	}
	fn, ok := node.Decls[0].(*ast.FuncDecl)
	if !ok {
		return nil
	}
	if len(fn.Body.List) != 1 {
		return &ast.BlockStmt{List: fn.Body.List}
	}
	return fn.Body.List[0]
}

func commentedOutCodePermittedStmt(stmt ast.Stmt) bool {
	switch stmt := stmt.(type) {
	case *ast.ExprStmt:
		switch x := stmt.X.(type) {
		case *ast.CallExpr:
			return false
		case *ast.UnaryExpr:
			return x.Op != token.ARROW
		default:
			return true
		}
	case *ast.LabeledStmt:
		return commentedOutCodePermittedStmt(stmt.Stmt)
	case *ast.DeclStmt:
		decl, ok := stmt.Decl.(*ast.GenDecl)
		return ok && decl.Tok == token.TYPE
	default:
		return false
	}
}
EOF
