func init() {
	register("deferUnlambda", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				d, ok := n.(*ast.DeferStmt)
				if !ok {
					return
				}
				call := d.Call
				if len(call.Args) != 0 || call.Ellipsis.IsValid() {
					return
				}
				lit, ok := call.Fun.(*ast.FuncLit)
				if !ok || lit.Type.Params == nil || len(lit.Type.Params.List) != 0 || lit.Type.Results != nil {
					return
				}
				if lit.Body == nil || len(lit.Body.List) != 1 {
					return
				}
				es, ok := lit.Body.List[0].(*ast.ExprStmt)
				if !ok {
					return
				}
				inner, ok := es.X.(*ast.CallExpr)
				if !ok || inner.Ellipsis.IsValid() {
					return
				}
				for _, arg := range inner.Args {
					if !isConst(info, arg) {
						return
					}
				}
				argsText := ""
				if len(inner.Args) != 0 {
					argsText = srcRange(ctx, inner.Args[0].Pos(), inner.Args[len(inner.Args)-1].End())
				}
				switch fn := inner.Fun.(type) {
				case *ast.Ident:
					if fn.Name == "panic" || fn.Name == "recover" {
						return
					}
					rg.report(d, "can rewrite as `defer "+fn.Name+"("+argsText+")`")
				case *ast.SelectorExpr:
					pkg, ok := fn.X.(*ast.Ident)
					if !ok {
						return
					}
					if _, ok := info.ObjectOf(pkg).(*types.PkgName); !ok {
						return
					}
					rg.report(d, "can rewrite as `defer "+rg.text(pkg)+"."+fn.Sel.Name+"("+argsText+")`")
				}
			})
			rg.flush()
		}), nil
	})
}
