func init() {
	register("deprecatedComment", func(ctx *CheckerContext) (FileWalker, error) {
		patterns := []*regexp.Regexp{
			regexp.MustCompile(`(?i)^this (?:function|type) is deprecated`),
			regexp.MustCompile(`(?i)^deprecated[.!]? use`),
			regexp.MustCompile(`(?i)^\[\[deprecated\]\]`),
			regexp.MustCompile(`(?i)^note: deprecated`),
			regexp.MustCompile(`(?i)^deprecated in`),
		}
		typos := []string{
			"Dprecated: ",
			"Derecated: ",
			"Depecated: ",
			"Deprcated: ",
			"Depreated: ",
			"Deprected: ",
			"Deprecaed: ",
			"Deprecatd: ",
			"Deprecate: ",
			"Derpecate: ",
			"Derpecated: ",
			"Depreacted: ",
		}
		return walkerFunc(func(f *ast.File) {
			walkDocComments(f, func(doc *ast.CommentGroup) {
				if strings.HasPrefix(doc.List[0].Text, "/*") {
					return
				}
				for _, c := range doc.List {
					l := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
					for _, re := range patterns {
						if re.MatchString(l) {
							ctx.Warn(c, "the proper format is `Deprecated: <text>`")
							return
						}
					}
					if len(l) >= len("Deprecated: ") {
						prefix := l[:len("Deprecated: ")]
						if prefix != "Deprecated: " && strings.EqualFold(prefix, "Deprecated: ") {
							ctx.Warn(c, "use `Deprecated: ` (note the casing) instead of `%s`", prefix)
							return
						}
					}
					if strings.HasPrefix(l, "Deprecated, ") {
						ctx.Warn(c, "use `:` instead of `,` in `Deprecated, `")
						return
					}
					for _, typo := range typos {
						if len(l) >= len(typo) && strings.EqualFold(l[:len(typo)], typo) {
							ctx.Warn(c, "typo in `%s`; should be `Deprecated`", l[:len(typo)-2])
							return
						}
					}
				}
			})
		}), nil
	})
}
EOF
