package lint

import (
	"go/ast"
)

type dupArgFunc struct {
	pkg   string
	name  string
	nargs int
	x, y  int
}

var dupArgFuncs = func() []dupArgFunc {
	var list []dupArgFunc
	add := func(pkg string, nargs, x, y int, names ...string) {
		for _, name := range names {
			list = append(list, dupArgFunc{pkg, name, nargs, x, y})
		}
	}
	add("", 2, 0, 1, "copy")
	add("math", 2, 0, 1, "Max", "Min", "Dim")
	add("reflect", 2, 0, 1, "Copy", "DeepEqual")
	for _, pkg := range []string{"strings", "bytes"} {
		add(pkg, 2, 0, 1, "Contains", "Compare", "Equal", "EqualFold", "HasPrefix", "HasSuffix", "Index", "LastIndex", "Split", "SplitAfter")
		add(pkg, 3, 0, 1, "SplitAfterN", "SplitN")
		add(pkg, 4, 1, 2, "Replace")
		add(pkg, 3, 1, 2, "ReplaceAll")
	}
	add("go/types", 2, 0, 1, "Identical", "IdenticalIgnoreTags")
	add("image/draw", 5, 0, 2, "Draw")
	add("slices", 2, 0, 1, "Equal", "Compare")
	add("maps", 2, 0, 1, "Equal")
	return list
}()

func init() {
	register("dupArg", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				call, ok := n.(*ast.CallExpr)
				if !ok || call.Ellipsis.IsValid() {
					return
				}
				// Method calls: $x.Equal($x) and friends.
				if sel, ok := call.Fun.(*ast.SelectorExpr); ok && len(call.Args) == 1 {
					switch sel.Sel.Name {
					case "Equal", "Equals", "Compare", "Cmp":
						if astEqual(sel.X, call.Args[0]) && isPure(info, sel.X) {
							rg.report(call, "suspicious method call with the same argument and receiver")
							return
						}
					}
				}
				for _, fn := range dupArgFuncs {
					if len(call.Args) != fn.nargs {
						continue
					}
					if fn.pkg == "" {
						if !isIdentNamed(call.Fun, fn.name) {
							continue
						}
					} else if !isPkgSel(info, call.Fun, fn.pkg, fn.name) {
						continue
					}
					x, y := call.Args[fn.x], call.Args[fn.y]
					if astEqual(x, y) && isPure(info, x) {
						rg.report(call, "suspicious duplicated args in "+rg.text(call))
					}
					return
				}
			})
			rg.flush()
		}), nil
	})
}
