package lint

import (
	"go/ast"
)

type astSet struct {
	items []ast.Node
}

func (s *astSet) insert(n ast.Node) bool {
	for _, x := range s.items {
		if astEqual(x, n) {
			return false
		}
	}
	s.items = append(s.items, n)
	return true
}

func init() {
	register("dupCase", func(ctx *CheckerContext) (FileWalker, error) {
		warn := func(n ast.Node) {
			ctx.Warn(n, "'case %s' is duplicated", n)
		}
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				switch stmt := stmt.(type) {
				case *ast.SwitchStmt:
					var set astSet
					for _, s := range stmt.Body.List {
						cc, ok := s.(*ast.CaseClause)
						if !ok {
							continue
						}
						for _, x := range cc.List {
							if !set.insert(x) {
								warn(x)
							}
						}
					}
				case *ast.SelectStmt:
					var set astSet
					for _, s := range stmt.Body.List {
						cc, ok := s.(*ast.CommClause)
						if !ok || cc.Comm == nil {
							continue
						}
						x := cc.Comm
						if !set.insert(x) {
							if es, ok := x.(*ast.ExprStmt); ok {
								warn(es.X)
							} else {
								warn(x)
							}
						}
					}
				}
			})
		}), nil
	})
}
