package lint

import (
	"go/ast"
	"go/types"
)

func init() {
	register("dupOption", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				call, ok := x.(*ast.CallExpr)
				if !ok || len(call.Args) == 0 || call.Ellipsis.IsValid() {
					return true
				}
				sig, ok := ctx.TypeOf(call.Fun).(*types.Signature)
				if !ok || !sig.Variadic() {
					return true
				}
				last := sig.Params().Len() - 1
				if last < 0 {
					return true
				}
				slice, ok := sig.Params().At(last).Type().(*types.Slice)
				if !ok || last > len(call.Args) {
					return true
				}
				elemSig, ok := slice.Elem().Underlying().(*types.Signature)
				if !ok || elemSig.Params().Len() == 0 {
					return true
				}
				seen := map[string]bool{}
				for _, arg := range call.Args[last:] {
					code := ctx.NodeString(arg)
					if seen[code] {
						ctx.Warn(arg, "function argument `%s` is duplicated", arg)
						continue
					}
					seen[code] = true
				}
				return true
			})
		}), nil
	})
}
