import (
	"go/ast"
)

func init() {
	register("elseif", func(ctx *CheckerContext) (FileWalker, error) {
		skipBalanced := ctx.BoolParam("skipBalanced")
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				ifstmt, ok := stmt.(*ast.IfStmt)
				if !ok {
					return
				}
				elseBody, ok := ifstmt.Else.(*ast.BlockStmt)
				if !ok || len(elseBody.List) != 1 {
					return
				}
				inner, ok := elseBody.List[0].(*ast.IfStmt)
				if !ok {
					return
				}
				balanced := len(ifstmt.Body.List) == 1
				if balanced {
					_, balanced = ifstmt.Body.List[0].(*ast.IfStmt)
				}
				if balanced && skipBalanced {
					return
				}
				if inner.Else != nil || inner.Init != nil {
					return
				}
				ctx.Warn(ifstmt.Else, "can replace 'else {if cond {}}' with 'else if cond {}'")
			})
		}), nil
	})
}
