							warn = true
							if prevCaseDefault {
								ctx.Warn(bs, "remove empty case containing only fallthrough to default case")
							} else if cc.List != nil {
								ctx.Warn(bs, "replace empty case containing only fallthrough with expression list")
							}
						}
					}
					if !warn {
						prevCaseDefault = cc.List == nil
					}
				}
			})
		}), nil
	})
}
