func init() {
	register("equalFold", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			unwrap := func(e ast.Expr, pkg, fn string) ast.Expr {
				call, ok := e.(*ast.CallExpr)
				if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, pkg, fn) {
					return nil
				}
				return call.Args[0]
			}
