				for _, fn := range []string{"ToLower", "ToUpper"} {
					var cands [][2]ast.Expr
					if x := unwrap(a, pkg, fn); x != nil {
						cands = append(cands, [2]ast.Expr{x, b})
						if y := unwrap(b, pkg, fn); y != nil {
							cands = append(cands, [2]ast.Expr{x, y})
						}
					}
					if y := unwrap(b, pkg, fn); y != nil {
						cands = append(cands, [2]ast.Expr{a, y})
					}
					for _, c := range cands {
						x, y := c[0], c[1]
						if isPure(info, x) && isPure(info, y) && rg.text(x) != rg.text(y) {
							return x, y, true
						}
					}
				}
				return nil, nil, false
			}
			walkAll(f, func(n ast.Node) {
				switch n := n.(type) {
				case *ast.BinaryExpr:
					if n.Op != token.EQL && n.Op != token.NEQ {
