package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	register("evalOrder", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				ret, ok := stmt.(*ast.ReturnStmt)
				if !ok || len(ret.Results) < 2 {
					return
				}
				for _, res := range ret.Results {
					id, ok := res.(*ast.Ident)
					if !ok {
						continue
					}
					addrTake := &ast.UnaryExpr{Op: token.AND, X: id}
					for _, res := range ret.Results {
						call, ok := res.(*ast.CallExpr)
						if !ok {
							continue
						}
						if sel, ok := call.Fun.(*ast.SelectorExpr); ok && astEqual(sel.X, id) {
							if fn, ok := ctx.TypesInfo.ObjectOf(sel.Sel).(*types.Func); ok {
								if sig, ok := fn.Type().(*types.Signature); ok && sig.Recv() != nil {
									if _, ok := sig.Recv().Type().(*types.Pointer); ok {
										ctx.Warn(call, "may want to evaluate %s before the return statement", call)
									}
								}
							}
						}
						for _, arg := range call.Args {
							if astEqual(addrTake, arg) {
								ctx.Warn(call, "may want to evaluate %s before the return statement", call)
							}
						}
					}
				}
			})
		}), nil
	})
}
