	register("flagName", func(ctx *CheckerContext) (FileWalker, error) {
		check := func(call *ast.CallExpr, arg ast.Expr) {
			cv := ctx.TypesInfo.Types[arg].Value
			if cv == nil || cv.Kind() != constant.String {
				return
			}
			name := constant.StringVal(cv)
			switch {
			case name == "":
				ctx.Warn(call, "empty flag name")
			case strings.HasPrefix(name, "-"):
				ctx.Warn(call, "flag name %q should not start with a hyphen", name)
			case strings.Contains(name, "="):
				ctx.Warn(call, "flag name %q should not contain '='", name)
			case strings.Contains(name, " "):
				ctx.Warn(call, "flag name %q contains whitespace", name)
			}
		}
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				call, ok := x.(*ast.CallExpr)
				if !ok {
					return true
				}
				sel, ok := call.Fun.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				id, ok := sel.X.(*ast.Ident)
				if !ok {
					return true
				}
				pn, ok := ctx.TypesInfo.ObjectOf(id).(*types.PkgName)
				if !ok || pn.Imported().Path() != "flag" {
					return true
				}
				switch sel.Sel.Name {
				case "Bool", "Duration", "Float64", "String", "Int", "Int64", "Uint", "Uint64":
					if len(call.Args) > 0 {
						check(call, call.Args[0])
