// sizeOf returns the size of typ; ok is false if size can't be computed.
func (c *CheckerContext) sizeOf(typ types.Type) (size int64, ok bool) {
	if typ == nil || c.Sizes == nil {
		return 0, false
	}
	if containsInvalid(typ) {
		return 0, false
	}
	defer func() {
		if r := recover(); r != nil {
			size, ok = 0, false
		}
	}()
	return c.Sizes.Sizeof(typ), true
}

// isGenericInstance reports whether typ is an instantiated generic named type.
// typeExpr is the type expression used in the source (may be nil); if it refers
// to a type alias, the type is not considered a generic instance (emulating
// alias-aware type checking).
func isGenericInstance(info *types.Info, typ types.Type, typeExpr ast.Expr) bool {
	named, ok := typ.(*types.Named)
	if !ok || named.TypeArgs().Len() == 0 {
		return false
	}
	if typeExpr != nil && refersToAlias(info, typeExpr) {
		return false
	}
	return true
}

func refersToAlias(info *types.Info, x ast.Expr) bool {
	var id *ast.Ident
	switch x := x.(type) {
	case *ast.Ident:
		id = x
	case *ast.SelectorExpr:
		id = x.Sel
	default:
		return false
	}
	tn, ok := info.ObjectOf(id).(*types.TypeName)
	return ok && tn.IsAlias()
}
