					size, ok := ctx.sizeOf(typ)
					if ok && size >= threshold {
						ctx.Warn(id, "%s is heavy (%d bytes); consider passing it by pointer", id, size)
					}
				}
			}
		}
		return walkerFunc(func(f *ast.File) {
			walkFuncDecls(f, func(decl *ast.FuncDecl) {
				if decl.Recv != nil && decl.Name.Name == "String" && decl.Type != nil &&
