{"command":"cd /workspace && cat > internal/lint/c_ifElseChain.go <<'EOF'
package lint

import (
	"go/ast"
)

func init() {
	register("ifElseChain", func(ctx *CheckerContext) (FileWalker, error) {
		minThreshold := ctx.IntParam("minThreshold")
		return walkerFunc(func(f *ast.File) {
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Body == nil {
					continue
				}
				visited := map[*ast.IfStmt]bool{}
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					stmt, ok := n.(*ast.IfStmt)
					if !ok || visited[stmt] {
						return true
					}
					count := 0
					ifstmt := stmt
				loop:
					for {
						if ifstmt.Init != nil {
							count = 0
							break
						}
						switch e := ifstmt.Else.(type) {
						case *ast.IfStmt:
							ifstmt = e
							visited[e] = true
							count++
						case *ast.BlockStmt:
							count++
							break loop
						default:
							break loop
						}
					}
					if count >= minThreshold {
						ctx.Warn(stmt, "rewrite if-else to switch statement")
					}
					return true
				})
			}
		}), nil
	})
}
EOF
