					stmt, ok := n.(*ast.IfStmt)
					if !ok || visited[stmt] {
						return true
					}
					count := 0
					ifstmt := stmt
				loop:
					for {
						if ifstmt.Init != nil {
							count = 0
							break
						}
						switch e := ifstmt.Else.(type) {
						case *ast.IfStmt:
							ifstmt = e
							visited[e] = true
							count++
						case *ast.BlockStmt:
							count++
							break loop
						default:
							break loop
						}
					}
					if count >= minThreshold {
						ctx.Warn(stmt, "rewrite if-else to switch statement")
					}
					return true
				})
			}
		}), nil
	})
}
EOF
