package lint

import (
	"go/ast"
	"go/types"
	"regexp"
	"strings"
)

func init() {
	register("mapKey", func(ctx *CheckerContext) (FileWalker, error) {
		suspiciousRE := regexp.MustCompile(`^ \S|\S $`)
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				lit, ok := x.(*ast.CompositeLit)
				if !ok || len(lit.Elts) < 2 {
					return true
				}
				typ := ctx.TypeOf(lit)
				if typ == nil {
					return true
				}
				m, ok := typ.Underlying().(*types.Map)
				if !ok {
					return true
				}
				b, ok := m.Key().Underlying().(*types.Basic)
				if !ok || (b.Kind() != types.String && b.Kind() != types.UntypedString) {
					return true
				}

				// Whitespace check.
				var wsKey *ast.BasicLit
				multi := false
				for _, elt := range lit.Elts {
					kv, ok := elt.(*ast.KeyValueExpr)
					if !ok {
						continue
					}
					key, ok := kv.Key.(*ast.BasicLit)
					if !ok || len(key.Value) < len(`" "`) {
						continue
					}
					s := key.Value[1 : len(key.Value)-1]
					if !strings.Contains(s, " ") {
						continue
					}
					if wsKey != nil {
						multi = true
						break
					}
