package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	register("offBy1", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			// matchIndexDef matches `$i := pkg.Index($s, $_)` and returns i, s.
			matchIndexDef := func(stmt ast.Stmt, pkg string) (*ast.Ident, ast.Expr) {
				assign, ok := stmt.(*ast.AssignStmt)
				if !ok || assign.Tok != token.DEFINE || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
					return nil, nil
				}
				id, ok := assign.Lhs[0].(*ast.Ident)
				if !ok {
					return nil, nil
				}
				call, ok := assign.Rhs[0].(*ast.CallExpr)
				if !ok || len(call.Args) != 2 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, pkg, "Index") {
					return nil, nil
				}
				return id, call.Args[0]
			}
			// matchSlicing matches `$_ := $slicing[$i:]` (or `=`) and returns slicing.
			matchSlicing := func(stmt ast.Stmt, tok token.Token, i *ast.Ident, low bool) ast.Expr {
				assign, ok := stmt.(*ast.AssignStmt)
				if !ok || assign.Tok != tok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
					return nil
				}
				sl, ok := assign.Rhs[0].(*ast.SliceExpr)
				if !ok || sl.Slice3 || sl.Max != nil {
					return nil
				}
				if low {
					if sl.High != nil || !astEqual(sl.Low, i) {
						return nil
					}
				} else {
					if sl.Low != nil || !astEqual(sl.High, i) {
						return nil
					}
				}
				return sl.X
			}
			type listRule struct {
				pkg  string
				tok  token.Token
				low  bool
				tmpl string
			}
			var listRules []listRule
			for _, low := range []bool{true, false} {
				tmpl := "Index() can return -1; maybe you wanted to do $s[$i+1:]"
				if !low {
					tmpl = "Index() can return -1; maybe you wanted to do $s[:$i+1]"
				}
				for _, pkg := range []string{"strings", "bytes"} {
					for _, tok := range []token.Token{token.DEFINE, token.ASSIGN} {
						listRules = append(listRules, listRule{pkg, tok, low, tmpl})
					}
				}
			}
			checkList := func(list []ast.Stmt) {
				for _, r := range listRules {
					for k := 0; k+1 < len(list); k++ {
						i, s := matchIndexDef(list[k], r.pkg)
						if i == nil {
							continue
						}
						slicing := matchSlicing(list[k+1], r.tok, i, r.low)
						if slicing == nil || rg.text(s) != rg.text(slicing) {
							continue
						}
						rg.report(slicing, interp(r.tmpl, map[string]string{"s": rg.text(s), "i": rg.text(i)}))
						k++
					}
				}
			}
			ast.Inspect(f, func(n ast.Node) bool {
				switch n := n.(type) {
				case *ast.BlockStmt:
					checkList(n.List)
				case *ast.CaseClause:
					checkList(n.Body)
				case *ast.CommClause:
					checkList(n.Body)
				case *ast.IndexExpr:
					call, ok := n.Index.(*ast.CallExpr)
					if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() || !isIdentNamed(call.Fun, "len") {
						break
					}
					x := n.X
					if !astEqual(x, call.Args[0]) || !isPure(info, x) {
						break
					}
					if _, ok := ctx.TypeOf(x).(*types.Slice); !ok {
						break
					}
					t := rg.text(x)
					rg.report(n, "index expr always panics; maybe you wanted "+t+"[len("+t+")-1]?")
				}
				return true
			})
			rg.flush()
		}), nil
	})
}
EOF
