package lint

import (
	"go/ast"
)

func init() {
	register("paramTypeCombine", func(ctx *CheckerContext) (FileWalker, error) {
		line := func(n ast.Node) int { return ctx.Fset.Position(n.Pos()).Line }
		_ = line
		optimize := func(params *ast.FieldList) *ast.FieldList {
			if params == nil || len(params.List) < 2 || len(params.List[0].Names) == 0 || params.List[0].Tag != nil {
				return params
			}
			if params.Opening.IsValid() && params.Closing.IsValid() &&
				ctx.Fset.Position(params.Opening).Line != ctx.Fset.Position(params.Closing).Line {
				return params
			}
			names := make([]*ast.Ident, len(params.List[0].Names))
			copy(names, params.List[0].Names)
			list := []*ast.Field{{Names: names, Type: params.List[0].Type}}
			for i, p := range params.List[1:] {
				names := make([]*ast.Ident, len(p.Names))
				copy(names, p.Names)
				if astEqual(p.Type, params.List[i].Type) {
					list[len(list)-1].Names = append(list[len(list)-1].Names, names...)
				} else {
					list = append(list, &ast.Field{Names: names, Type: params.List[i+1].Type})
				}
			}
			return &ast.FieldList{List: list}
		}
		return walkerFunc(func(f *ast.File) {
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok {
					continue
				}
				typ := &ast.FuncType{
					TypeParams: fn.Type.TypeParams,
					Params:     optimize(fn.Type.Params),
					Results:    optimize(fn.Type.Results),
				}
				if !astEqual(typ, fn.Type) {
					ctx.Warn(fn.Type, "%s could be replaced with %s", fn.Type, typ)
				}
			}
		}), nil
	})
}
