)

func init() {
	register("preferWriteByte", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				call, ok := n.(*ast.CallExpr)
				if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() {
					return
				}
				sel, ok := call.Fun.(*ast.SelectorExpr)
				if !ok || sel.Sel.Name != "WriteRune" {
					return
				}
				typ := ctx.TypeOf(sel.X)
				if typ == nil || !hasMethod(typ, "WriteByte") {
					return
				}
				c := call.Args[0]
				v := constValue(info, c)
				if v == nil {
					return
				}
				v = constant.ToInt(v)
				if v.Kind() != constant.Int {
					return
				}
				iv, ok := constant.Int64Val(v)
				if !ok || iv >= 0x80 {
					return
				}
				t := rg.text(c)
				rg.report(call, "consider writing single byte rune "+t+" with "+rg.text(sel.X)+".WriteByte("+t+")")
			})
			rg.flush()
		}), nil
	})
}

