package lint

import (
	"go/ast"
	"go/token"
)

func init() {
	register("rangeAppendAll", func(ctx *CheckerContext) (FileWalker, error) {
		isSliceLiteral := func(arg ast.Expr) bool {
			switch v := arg.(type) {
			case *ast.CompositeLit:
				return true
			case *ast.CallExpr:
				if _, ok := v.Fun.(*ast.ArrayType); ok && len(v.Args) == 1 {
					return isIdentNamed(v.Args[0], "nil")
				}
			}
			return false
		}
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				rs, ok := stmt.(*ast.RangeStmt)
				if !ok || len(rs.Body.List) == 0 {
					return
				}
				rangeIdent, ok := rs.X.(*ast.Ident)
				if !ok {
					return
				}
				rangeObj := ctx.TypesInfo.ObjectOf(rangeIdent)
				ast.Inspect(rs.Body, func(n ast.Node) bool {
					call, ok := n.(*ast.CallExpr)
					if !ok || len(call.Args) != 2 || call.Ellipsis == token.NoPos || qualifiedName(call.Fun) != "append" {
						return true
					}
					if isSliceLiteral(call.Args[0]) {
						return true
					}
					from, ok := call.Args[1].(*ast.Ident)
					if !ok {
						return true
					}
					if ctx.TypesInfo.ObjectOf(from) == rangeObj {
						ctx.Warn(from, "append all `%s` data while range it", from)
					}
					return true
				})
			})
		}), nil
	})
}
