package lint

import (
	"go/ast"
	"go/types"
	"strings"
)

func isUnitTestFunc(ctx *CheckerContext, fn *ast.FuncDecl) bool {
	if !strings.HasPrefix(fn.Name.Name, "Test") {
		return false
	}
	typ := ctx.TypesInfo.TypeOf(fn.Name)
	if typ == nil {
		if obj := ctx.TypesInfo.ObjectOf(fn.Name); obj != nil {
			typ = obj.Type()
		}
	}
	if sig, ok := typ.(*types.Signature); ok {
		return sig.Results().Len() == 0 &&
			sig.Params().Len() == 1 &&
			sig.Params().At(0).Type().String() == "*testing.T"
	}
	return false
}

func init() {
	register("rangeExprCopy", func(ctx *CheckerContext) (FileWalker, error) {
		threshold := int64(ctx.IntParam("sizeThreshold"))
		skipTests := ctx.BoolParam("skipTestFuncs")
		return walkerFunc(func(f *ast.File) {
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Body == nil || (skipTests && isUnitTestFunc(ctx, fn)) {
					continue
				}
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					rng, ok := n.(*ast.RangeStmt)
					if !ok || rng.Key == nil || rng.Value == nil {
						return true
					}
					tv := ctx.TypesInfo.Types[rng.X]
					if !tv.Addressable() {
						return true
					}
					if _, ok := tv.Type.(*types.Array); !ok {
						return true
					}
					if size, ok := ctx.sizeOf(tv.Type); ok && size >= threshold {
						ctx.Warn(rng, "copy of %s (%d bytes) can be avoided with &%s", rng.X, size, rng.X)
					}
					return true
				})
			}
		}), nil
	})
}
EOF
