package lint

import (
	"go/ast"
	"go/token"
)

func init() {
	register("singleCaseSwitch", func(ctx *CheckerContext) (FileWalker, error) {
		hasBreak := func(stmt ast.Stmt) bool {
			found := false
			ast.Inspect(stmt, func(x ast.Node) bool {
				switch x := x.(type) {
				case *ast.BranchStmt:
					if x.Tok == token.BREAK {
						found = true
					}
				case *ast.ForStmt, *ast.RangeStmt, *ast.SelectStmt, *ast.SwitchStmt:
					return false
				}
				return true
			})
			return found
		}
		check := func(stmt ast.Stmt, body *ast.BlockStmt) {
			if len(body.List) != 1 {
				return
			}
			cc, ok := body.List[0].(*ast.CaseClause)
			if !ok || hasBreak(cc) {
				return
			}
			switch {
			case cc.List == nil:
				ctx.Warn(stmt, "found switch with default case only")
			case len(cc.List) == 1:
				ctx.Warn(stmt, "should rewrite switch statement to if statement")
			}
		}
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				switch stmt := stmt.(type) {
				case *ast.SwitchStmt:
					check(stmt, stmt.Body)
				case *ast.TypeSwitchStmt:
					check(stmt, stmt.Body)
				}
			})
		}), nil
	})
}
EOF
