package lint

import (
	"go/ast"
	"go/token"
)

func init() {
	register("sloppyLen", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
