package lint

import (
	"go/ast"
	"go/token"
)

func init() {
	register("sloppyReassign", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
				ifStmt, ok := stmt.(*ast.IfStmt)
				if !ok {
					return
				}
				assign, ok := ifStmt.Init.(*ast.AssignStmt)
				if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
					return
				}
				body := ifStmt.Body.List
				if len(body) != 1 {
					return
				}
				re, ok := assign.Lhs[0].(*ast.Ident)
				if !ok || re.Name == "" {
					return
				}
				eqToNil := &ast.BinaryExpr{Op: token.NEQ, X: re, Y: &ast.Ident{Name: "nil"}}
				if !astEqual(ifStmt.Cond, eqToNil) {
					return
				}
				ret, ok := body[0].(*ast.ReturnStmt)
				if !ok {
					return
				}
				for _, res := range ret.Results {
					if astEqual(re, res) {
						suggest := *assign
						suggest.Tok = token.DEFINE
						ctx.Warn(assign, "re-assignment to `%s` can be replaced with `%s`", re.Name, &suggest)
						break
					}
				}
			})
		}), nil
	})
}
