				return typeIsRowsLike(typ.Elem())
			case *types.Named:
				return typ.Obj().Name() == "Rows"
			}
			return false
		}
		funcIsQuery := func(sel *ast.SelectorExpr) bool {
			switch sel.Sel.Name {
			case "Query", "QueryContext", "Queryx", "QueryxContext":
			default:
				return false
			}
			t := ctx.TypeOf(sel)
			if t == nil {
				return false
			}
			sig, ok := t.Underlying().(*types.Signature)
			if !ok || sig.Results() == nil || sig.Results().Len() != 2 {
				return false
			}
			return typeIsRowsLike(sig.Results().At(0).Type())
		}
		funcIsExec := func(fn *types.Func) bool {
			if fn.Name() != "Exec" {
				return false
			}
			sig, ok := fn.Type().(*types.Signature)
			if !ok || sig.Results() == nil || sig.Results().Len() != 2 {
				return false
			}
			params := sig.Params()
			if params == nil || params.Len() == 0 {
				return false
			}
			b, ok := params.At(0).Type().(*types.Basic)
			return ok && b.Kind() == types.String
		}
		var typeHasExec func(typ types.Type) bool
		typeHasExec = func(typ types.Type) bool {
			switch typ := typ.(type) {
			case *types.Struct:
				for i := 0; i < typ.NumFields(); i++ {
					if typeHasExec(typ.Field(i).Type()) {
						return true
					}
				}
			case *types.Interface:
				for i := 0; i < typ.NumMethods(); i++ {
					if funcIsExec(typ.Method(i)) {
						return true
					}
				}
			case *types.Pointer:
				return typeHasExec(typ.Elem())
			case *types.Named:
				for i := 0; i < typ.NumMethods(); i++ {
					if funcIsExec(typ.Method(i)) {
						return true
					}
				}
				switch ut := typ.Underlying().(type) {
				case *types.Interface:
					return typeHasExec(ut)
				case *types.Struct:
