						field := ut.Field(i)
						if !field.Embedded() {
							continue
						}
						if typeHasExec(field.Type()) {
							return true
						}
					}
				}
			}
			return false
		}
		return walkerFunc(func(f *ast.File) {
			walkStmts(f, func(stmt ast.Stmt) {
