	"go/ast"
)

func init() {
	register("stringConcatSimplify", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				call, ok := n.(*ast.CallExpr)
				if !ok || len(call.Args) != 2 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, "strings", "Join") {
					return
				}
				lit, ok := call.Args[0].(*ast.CompositeLit)
				if !ok {
					return
				}
				arr, ok := lit.Type.(*ast.ArrayType)
				if !ok || arr.Len != nil || !isIdentNamed(arr.Elt, "string") {
					return
				}
				for _, elt := range lit.Elts {
					if _, ok := elt.(*ast.KeyValueExpr); ok {
						return
					}
				}
				glue := call.Args[1]
				empty := isStringLit(glue, "")
				switch {
				case len(lit.Elts) == 2 && empty:
					rg.report(call, "suggestion: "+rg.text(lit.Elts[0])+" + "+rg.text(lit.Elts[1]))
				case len(lit.Elts) == 3 && empty:
					rg.report(call, "suggestion: "+rg.text(lit.Elts[0])+" + "+rg.text(lit.Elts[1])+" + "+rg.text(lit.Elts[2]))
				case len(lit.Elts) == 2:
					rg.report(call, "suggestion: "+rg.text(lit.Elts[0])+" + "+rg.text(glue)+" + "+rg.text(lit.Elts[1]))
				}
			})
			rg.flush()
		}), nil
	})
}
