						}
					case sel.Sel.Name == "FindAllIndex" && len(n.Args) == 2:
						if s := unbytes(n.Args[0]); s != nil && isRegexpPtr(sel.X) {
							rg.report(n, "suggestion: "+rg.text(sel.X)+".FindAllStringIndex("+rg.text(s)+", "+rg.text(n.Args[1])+")")
						}
					}
				case *ast.BinaryExpr:
					if n.Op != token.EQL && n.Op != token.NEQ {
						return
					}
					b := unconv(n.X, "string")
					if b == nil {
						return
					}
					if isStringLit(n.Y, "") {
						if !isBytes(b) {
							return
						}
						if n.Op == token.EQL {
							rg.report(n, "suggestion: len("+rg.text(b)+") == 0")
						} else {
							rg.report(n, "suggestion: len("+rg.text(b)+") != 0")
						}
						return
					}
					y := unconv(n.Y, "string")
					if y == nil || !isBytes(b) || !isBytes(y) {
						return
					}
					if n.Op == token.EQL {
						rg.report(n, "suggestion: bytes.Equal("+rg.text(b)+", "+rg.text(y)+")")
					} else {
						rg.report(n, "suggestion: !bytes.Equal("+rg.text(b)+", "+rg.text(y)+")")
					}
				}
			})
			rg.flush()
		}), nil
	})
}
