func init() {
	register("stringsCompare", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			isNegOne := func(x ast.Expr) bool {
				u, ok := x.(*ast.UnaryExpr)
				return ok && u.Op == token.SUB && isIntLit(u.X, 1)
			}
			walkAll(f, func(n ast.Node) {
				e, ok := n.(*ast.BinaryExpr)
				if !ok {
					return
				}
				call, ok := e.X.(*ast.CallExpr)
				if !ok || len(call.Args) != 2 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, "strings", "Compare") {
					return
				}
				var op string
				switch {
				case e.Op == token.EQL && isIntLit(e.Y, 0):
					op = "=="
				case (e.Op == token.EQL && isNegOne(e.Y)) || (e.Op == token.LSS && isIntLit(e.Y, 0)):
					op = "<"
				case (e.Op == token.EQL && isIntLit(e.Y, 1)) || (e.Op == token.GTR && isIntLit(e.Y, 0)):
