package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	register("syncMapLoadAndDelete", func(ctx *CheckerContext) (FileWalker, error) {
		isSyncMapPtr := func(x ast.Expr) bool {
			ptr, ok := ctx.TypeOf(x).(*types.Pointer)
			if !ok {
				return false
			}
			named, ok := ptr.Elem().(*types.Named)
			return ok && named.Obj().Name() == "Map" && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == "sync"
		}
		return walkerFunc(func(f *ast.File) {
			if !ctx.GoVersion.GreaterOrEqual(GoVersion{1, 15}) {
				return
			}
			rg := newRG(ctx)
			walkStmtListsAll(f, func(list []ast.Stmt) {
				for i := 0; i+1 < len(list); i++ {
					assign, ok := list[i].(*ast.AssignStmt)
					if !ok || assign.Tok != token.DEFINE || len(assign.Lhs) != 2 || len(assign.Rhs) != 1 {
						continue
					}
					okVar := assign.Lhs[1]
					call, ok := assign.Rhs[0].(*ast.CallExpr)
					if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() {
						continue
					}
					sel, ok := call.Fun.(*ast.SelectorExpr)
					if !ok || sel.Sel.Name != "Load" {
						continue
					}
					m, k := sel.X, call.Args[0]
					ifs, ok := list[i+1].(*ast.IfStmt)
					if !ok || ifs.Init != nil || ifs.Else != nil || !astEqual(ifs.Cond, okVar) || len(ifs.Body.List) == 0 {
						continue
					}
					es, ok := ifs.Body.List[0].(*ast.ExprStmt)
					if !ok {
						continue
					}
					del, ok := es.X.(*ast.CallExpr)
					if !ok || len(del.Args) != 1 || del.Ellipsis.IsValid() {
						continue
					}
					dsel, ok := del.Fun.(*ast.SelectorExpr)
					if !ok || dsel.Sel.Name != "Delete" || !astEqual(dsel.X, m) || !astEqual(del.Args[0], k) {
						continue
					}
					if !isSyncMapPtr(m) {
						continue
					}
					rg.report(list[i], "use "+rg.text(m)+".LoadAndDelete to perform load+delete operations atomically")
					i++
				}
			})
			rg.flush()
		}), nil
	})
}
EOF
