package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

func isNamedType(typ types.Type, pkgPath, name string) bool {
	named, ok := typ.(*types.Named)
	return ok && named.Obj().Name() == name && named.Obj().Pkg() != nil && named.Obj().Pkg().Path() == pkgPath
}

func init() {
	register("timeExprSimplify", func(ctx *CheckerContext) (FileWalker, error) {
		isTime := func(x ast.Expr) bool {
			typ := ctx.TypeOf(x)
			if typ == nil {
				return false
			}
			if isNamedType(typ, "time", "Time") {
				return true
			}
			if ptr, ok := typ.(*types.Pointer); ok {
				return isNamedType(ptr.Elem(), "time", "Time")
			}
			return false
		}
		return walkerFunc(func(f *ast.File) {
			if !ctx.GoVersion.GreaterOrEqual(GoVersion{1, 17}) {
				return
			}
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				e, ok := n.(*ast.BinaryExpr)
				if !ok || !isIntLit(e.Y, 1000) {
					return
				}
				var method, suggest string
				switch e.Op {
				case token.QUO:
					method, suggest = "Unix", "UnixMilli"
				case token.MUL:
					method, suggest = "UnixNano", "UnixMicro"
				default:
					return
				}
				t := matchMethodCall(e.X, method, 0)
				if t == nil || !isTime(t) {
					return
				}
				rg.report(e, "use "+rg.text(t)+"."+suggest+"() instead of "+rg.text(e))
			})
			rg.flush()
		}), nil
	})
}
