package lint

import (
	"go/ast"
	"go/types"
)

func init() {
	register("tooManyResultsChecker", func(ctx *CheckerContext) (FileWalker, error) {
		maxResults := ctx.IntParam("maxResults")
		return walkerFunc(func(f *ast.File) {
			walkFuncDecls(f, func(decl *ast.FuncDecl) {
				var n int
				if obj := ctx.TypesInfo.ObjectOf(decl.Name); obj != nil {
					if sig, ok := obj.Type().(*types.Signature); ok {
						n = sig.Results().Len()
					}
				} else if decl.Type.Results != nil {
					n = decl.Type.Results.NumFields()
				}
				if n > maxResults {
					ctx.Warn(decl, "function has more than %d results, consider to simplify the function", maxResults)
				}
			})
		}), nil
	})
}
EOF
