package lint

import (
	"go/ast"
	"go/token"
	"go/types"
)

func init() {
	register("truncateCmp", func(ctx *CheckerContext) (FileWalker, error) {
		skipArch := ctx.BoolParam("skipArchDependent")
		isTruncCast := func(x ast.Expr) bool {
			call, ok := x.(*ast.CallExpr)
			if !ok {
				return false
			}
			id, ok := call.Fun.(*ast.Ident)
			if !ok {
				return false
			}
			switch id.Name {
			case "int8", "int16", "int32", "uint8", "uint16", "uint32":
				return true
			case "int", "uint":
				return !skipArch
			}
			return false
		}
		basicOf := func(x ast.Expr) *types.Basic {
			typ := ctx.TypeOf(x)
			if typ == nil {
				return nil
			}
			b, _ := typ.Underlying().(*types.Basic)
			return b
		}
		checkCmp := func(cmpX, cmpY ast.Expr) {
			xcast := cmpX.(*ast.CallExpr)
			if len(xcast.Args) != 1 {
				return
			}
			x := xcast.Args[0]
			y := cmpY
			xtyp := basicOf(x)
			if xtyp == nil || xtyp.Info()&types.IsInteger == 0 {
				return
			}
			ytyp := basicOf(y)
			if ytyp == nil || xtyp.Info() != ytyp.Info() {
				return
			}
			xsize, ok := ctx.sizeOf(xtyp)
			if !ok {
				return
			}
			ysize, ok := ctx.sizeOf(ytyp)
			if !ok {
				return
			}
			if xsize <= ysize {
				return
			}
			if skipArch {
				switch xtyp.Kind() {
				case types.Int, types.Uint, types.Uintptr:
					return
				}
			}
			ctx.Warn(xcast, "truncation in comparison %d->%d bit; cast the other operand to %s instead", xsize*8, ysize*8, xtyp.Name())
		}
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				cmp, ok := x.(*ast.BinaryExpr)
				if !ok {
					return true
				}
				switch cmp.Op {
				case token.LSS, token.GTR, token.LEQ, token.GEQ, token.EQL, token.NEQ:
				default:
					return true
				}
				if _, ok := cmp.X.(*ast.BasicLit); ok {
					return true
				}
				if _, ok := cmp.Y.(*ast.BasicLit); ok {
					return true
				}
				l := isTruncCast(cmp.X)
				r := isTruncCast(cmp.Y)
				switch {
				case l && r:
				case l:
					checkCmp(cmp.X, cmp.Y)
				case r:
					checkCmp(cmp.Y, cmp.X)
				}
				return true
			})
		}), nil
	})
}
EOF
