func init() {
	register("typeAssertChain", func(ctx *CheckerContext) (FileWalker, error) {
		getTypeAssert := func(ifstmt *ast.IfStmt) *ast.TypeAssertExpr {
			assign, ok := ifstmt.Init.(*ast.AssignStmt)
			if !ok || len(assign.Lhs) != 2 || len(assign.Rhs) != 1 {
				return nil
			}
			if _, ok := assign.Lhs[0].(*ast.Ident); !ok || assign.Tok != token.DEFINE {
				return nil
			}
			if !astEqual(assign.Lhs[1], ifstmt.Cond) {
				return nil
			}
			assert, _ := assign.Rhs[0].(*ast.TypeAssertExpr)
			return assert
		}
		return walkerFunc(func(f *ast.File) {
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Body == nil {
					continue
				}
				visited := map[*ast.IfStmt]bool{}
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					stmt, ok := n.(*ast.IfStmt)
					if !ok || visited[stmt] {
						return true
					}
					assert := getTypeAssert(stmt)
					if assert == nil {
						return true
					}
					count := 1
					x := assert.X
					cur := stmt
					for {
						next, ok := cur.Else.(*ast.IfStmt)
						if !ok {
							break
