						a := getTypeAssert(next)
						if a == nil || !astEqual(a.X, x) {
							break
						}
						visited[next] = true
						cur = next
						count++
					}
					if count >= 2 {
						ctx.Warn(stmt, "rewrite if-else to type switch statement")
					}
					return true
				})
			}
