)

func init() {
	register("typeDefFirst", func(ctx *CheckerContext) (FileWalker, error) {
		var receiverType func(e ast.Expr) string
		receiverType = func(e ast.Expr) string {
			switch e := e.(type) {
			case *ast.StarExpr:
				return receiverType(e.X)
			case *ast.Ident:
				return e.Name
			case *ast.IndexExpr:
				return receiverType(e.X)
			case *ast.IndexListExpr:
				return receiverType(e.X)
			case *ast.ParenExpr:
				return receiverType(e.X)
			}
			return ""
		}
		return walkerFunc(func(f *ast.File) {
			tracked := map[string]bool{}
			for _, decl := range f.Decls {
				switch decl := decl.(type) {
				case *ast.FuncDecl:
					if decl.Recv == nil || len(decl.Recv.List) == 0 {
						continue
					}
					tracked[receiverType(decl.Recv.List[0].Type)] = true
				case *ast.GenDecl:
