func init() {
	register("underef", func(ctx *CheckerContext) (FileWalker, error) {
		skipRecvDeref := ctx.BoolParam("skipRecvDeref")
		isPtrRecvMethodCall := func(fn *ast.Ident) bool {
			sig, ok := ctx.TypeOf(fn).(*types.Signature)
			if ok && sig != nil && sig.Recv() != nil {
				_, ok := sig.Recv().Type().(*types.Pointer)
				return ok
			}
			return false
		}
		checkStarExpr := func(e *ast.StarExpr) bool {
			typ := ctx.TypeOf(e.X)
			if typ == nil {
				return false
			}
			ptr, ok := typ.Underlying().(*types.Pointer)
			if !ok {
				return false
			}
			switch ptr.Elem().Underlying().(type) {
			case *types.Pointer, *types.Interface:
				return false
			}
			return true
		}
		checkArray := func(e *ast.StarExpr) bool {
			ptr, ok := ctx.TypeOf(e.X).(*types.Pointer)
			if !ok {
				return false
			}
			_, ok = ptr.Elem().(*types.Array)
			return ok
		}
		underef := func(x *ast.ParenExpr) ast.Expr {
			d := x.X.(*ast.StarExpr).X
			if _, ok := d.(*ast.StarExpr); ok {
				return &ast.ParenExpr{X: d}
			}
			return d
		}
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				switch n := x.(type) {
				case *ast.SelectorExpr:
					p, ok := n.X.(*ast.ParenExpr)
					if !ok {
						return true
					}
					if skipRecvDeref && isPtrRecvMethodCall(n.Sel) {
						return true
					}
					if star, ok := p.X.(*ast.StarExpr); ok && checkStarExpr(star) {
						ctx.Warn(n, "could simplify %s to %s.%s", n, underef(p), n.Sel.Name)
					}
				case *ast.IndexExpr:
					p, ok := n.X.(*ast.ParenExpr)
					if !ok {
						return true
