package lint

import (
	"go/ast"
	"go/token"
)

func containsNode(root ast.Node, pred func(ast.Node) bool) bool {
	if root == nil || isNilNode(root) {
		return false
	}
	found := false
	ast.Inspect(root, func(n ast.Node) bool {
		if found || n == nil {
			return false
		}
		if pred(n) {
			found = true
			return false
		}
		return true
	})
	return found
}

func init() {
	register("unlabelStmt", func(ctx *CheckerContext) (FileWalker, error) {
		canBreakFrom := func(n ast.Node) bool {
			switch n.(type) {
			case *ast.RangeStmt, *ast.ForStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
				return true
			}
			return false
		}
		isLoop := func(n ast.Node) bool {
			switch n.(type) {
			case *ast.RangeStmt, *ast.ForStmt:
				return true
			}
			return false
		}
		blockStmtOf := func(n ast.Node) *ast.BlockStmt {
			switch n := n.(type) {
			case *ast.RangeStmt:
				return n.Body
			case *ast.ForStmt:
				return n.Body
			case *ast.SwitchStmt:
				return n.Body
			case *ast.TypeSwitchStmt:
				return n.Body
			case *ast.SelectStmt:
				return n.Body
			}
			return nil
		}
		usesLabel := func(b *ast.BlockStmt, name string) bool {
			if b == nil {
				return false
			}
			return containsNode(b, func(n ast.Node) bool {
				br, ok := n.(*ast.BranchStmt)
				return ok && br.Label != nil && br.Label.Name == name &&
					(br.Tok == token.CONTINUE || br.Tok == token.BREAK)
			})
		}
		return walkerFunc(func(f *ast.File) {
			for _, decl := range f.Decls {
				fn, ok := decl.(*ast.FuncDecl)
				if !ok || fn.Body == nil {
					continue
				}
				if containsNode(fn.Body, func(n ast.Node) bool {
					br, ok := n.(*ast.BranchStmt)
					return ok && br.Tok == token.GOTO
				}) {
					continue
				}
				ast.Inspect(fn.Body, func(n ast.Node) bool {
					labeled, ok := n.(*ast.LabeledStmt)
					if !ok || !canBreakFrom(labeled.Stmt) {
						return true
					}
					name := labeled.Label.Name
					matchUsage := func(n ast.Node) bool {
						return canBreakFrom(n) && usesLabel(blockStmtOf(n), name)
					}
					if !containsNode(blockStmtOf(labeled.Stmt), matchUsage) {
						ctx.Warn(labeled, "label %s is redundant", labeled.Label)
						return true
					}
					if !isLoop(labeled.Stmt) {
						return true
					}
					body := blockStmtOf(labeled.Stmt)
					if len(body.List) == 0 {
						return true
					}
					last := body.List[len(body.List)-1]
					if !isLoop(last) {
						return true
					}
					var br *ast.BranchStmt
					ast.Inspect(blockStmtOf(last), func(n ast.Node) bool {
						if br != nil || n == nil {
							return false
						}
						if _, ok := n.(*ast.SelectStmt); ok {
							return false
						}
						if b, ok := n.(*ast.BranchStmt); ok && b.Label != nil && b.Label.Name == name && b.Tok == token.CONTINUE {
							br = b
							return false
						}
						return true
					})
					if br != nil {
						ctx.Warn(br, "change `continue %s` to `break`", name)
					}
					return true
				})
			}
		}), nil
	})
}
EOF
