package lint

import (
	"go/ast"
	"go/types"
)

func init() {
	register("unlambda", func(ctx *CheckerContext) (FileWalker, error) {
		return walkerFunc(func(f *ast.File) {
			walkExprs(f, func(x ast.Expr) bool {
				fn, ok := x.(*ast.FuncLit)
				if !ok || fn.Body == nil || len(fn.Body.List) != 1 {
					return true
				}
				ret, ok := fn.Body.List[0].(*ast.ReturnStmt)
				if !ok || len(ret.Results) != 1 {
					return true
				}
				result, ok := ret.Results[0].(*ast.CallExpr)
				if !ok {
					return true
				}
				callable := qualifiedName(result.Fun)
				if callable == "" || isBuiltinName(callable) {
					return true
				}
				hasVars := containsNode(result.Fun, func(n ast.Node) bool {
					id, ok := n.(*ast.Ident)
					if !ok {
						return false
					}
					obj, ok := ctx.TypesInfo.ObjectOf(id).(*types.Var)
					if !ok {
						return false
					}
					_, isStruct := obj.Type().Underlying().(*types.Struct)
					return !isStruct
				})
				if hasVars {
					return true
				}
				fnType := ctx.TypeOf(fn)
				resultType := ctx.TypeOf(result.Fun)
				if fnType == nil || resultType == nil || !types.Identical(fnType, resultType) {
					return true
				}
				sig, ok := fnType.(*types.Signature)
				if !ok {
					return true
				}
				var names []*ast.Ident
				for _, field := range fn.Type.Params.List {
					names = append(names, field.Names...)
				}
				if len(names) != len(result.Args) {
					return true
				}
				for i, arg := range result.Args {
					id, ok := arg.(*ast.Ident)
					if !ok || id.Name != names[i].Name || id.Name == "_" {
						return true
					}
				}
				if sig.Variadic() != result.Ellipsis.IsValid() {
					return true
				}
				ctx.Warn(fn, "replace `%s` with `%s`", fn, callable)
				return true
			})
		}), nil
	})
}
EOF
