package lint

import (
	"go/ast"
	"go/types"
)

func init() {
	register("unnamedResult", func(ctx *CheckerContext) (FileWalker, error) {
		checkExported := ctx.BoolParam("checkExported")
		var typeName func(typ types.Type) string
		typeName = func(typ types.Type) string {
			switch typ := typ.(type) {
			case *types.Array:
				return typeName(typ.Elem())
			case *types.Pointer:
				return typeName(typ.Elem())
			case *types.Slice:
				return typeName(typ.Elem())
			case *types.Named:
				return typ.Obj().Name()
			}
			return ""
		}
		return walkerFunc(func(f *ast.File) {
			walkFuncDecls(f, func(decl *ast.FuncDecl) {
				if checkExported && !ast.IsExported(decl.Name.Name) {
					return
				}
				results := decl.Type.Results
				switch {
				case results == nil:
					return
				case len(results.List) != 0 && results.List[0].Names != nil:
					return
				}
				tn := func(x ast.Expr) string { return typeName(ctx.TypeOf(x)) }
				isError := func(x ast.Expr) bool { return qualifiedName(x) == "error" }
				isBool := func(x ast.Expr) bool { return qualifiedName(x) == "bool" }
				if results.NumFields() == 2 {
					typ1, typ2 := results.List[0].Type, results.List[1].Type
					name1, name2 := tn(typ1), tn(typ2)
					cond := (name1 != name2 && name2 != "") ||
						(!isError(typ1) && isError(typ2)) ||
						(!isBool(typ1) && isBool(typ2))
					if !cond {
						ctx.Warn(decl, "consider giving a name to these results")
					}
					return
				}
				seen := map[string]bool{}
				for i := range results.List {
					typ := results.List[i].Type
					name := tn(typ)
					isLast := i == results.NumFields()-1
					cond := !seen[name] || (isLast && (isError(typ) || isBool(typ)))
					if !cond {
						ctx.Warn(decl, "consider giving a name to these results")
						return
					}
					seen[name] = true
				}
			})
		}), nil
	})
}
