package lint

import (
	"go/ast"
	"go/token"
)

func init() {
	register("unnecessaryBlock", func(ctx *CheckerContext) (FileWalker, error) {
		hasDefinitions := func(b *ast.BlockStmt) bool {
			for _, s := range b.List {
				switch s := s.(type) {
				case *ast.AssignStmt:
					if s.Tok == token.DEFINE {
						return true
					}
				case *ast.DeclStmt:
					if decl, ok := s.Decl.(*ast.GenDecl); ok && len(decl.Specs) != 0 {
						return true
					}
				}
			}
			return false
		}
		return walkerFunc(func(f *ast.File) {
			walkStmtLists(f, func(parent ast.Node, list []ast.Stmt) {
				switch parent.(type) {
				case *ast.CaseClause, *ast.CommClause:
					if len(list) == 1 {
						if _, ok := list[0].(*ast.BlockStmt); ok {
							ctx.Warn(list[0], "case statement doesn't require a block statement")
							return
						}
					}
				}
				for _, s := range list {
					if b, ok := s.(*ast.BlockStmt); ok && !hasDefinitions(b) {
						ctx.Warn(b, "block doesn't have definitions, can be simply deleted")
					}
				}
			})
		}), nil
	})
}
EOF
