func init() {
	register("valSwap", func(ctx *CheckerContext) (FileWalker, error) {
		asg := func(s ast.Stmt, tok token.Token) (ast.Expr, ast.Expr, bool) {
			a, ok := s.(*ast.AssignStmt)
			if !ok || a.Tok != tok || len(a.Lhs) != 1 || len(a.Rhs) != 1 {
				return nil, nil, false
			}
			return a.Lhs[0], a.Rhs[0], true
		}
		return walkerFunc(func(f *ast.File) {
			rg := newRG(ctx)
			walkStmtListsAll(f, func(list []ast.Stmt) {
