					tmp, y, ok := asg(list[i], token.DEFINE)
					if !ok {
						continue
					}
					y2, x, ok := asg(list[i+1], token.ASSIGN)
					if !ok || !astEqual(y, y2) {
						continue
					}
					x2, tmp2, ok := asg(list[i+2], token.ASSIGN)
					if !ok || !astEqual(x, x2) || !astEqual(tmp, tmp2) {
						continue
					}
					rg.report(list[i], "can re-write as `"+rg.text(y)+", "+rg.text(x)+" = "+rg.text(x)+", "+rg.text(y)+"`")
					i += 2
				}
			})
			rg.flush()
		}), nil
	})
}
