					if isNegOne(call.Args[3]) {
						report("strings.ReplaceAll")
					}
				case len(call.Args) == 2 && isPkgSel(info, call.Fun, "strings", "Map"):
					if isPkgSel(info, call.Args[0], "unicode", "ToTitle") {
						report("strings.ToTitle")
					}
