							report("bytes.Split")
						}
					}
				case len(call.Args) == 4 && isPkgSel(info, call.Fun, "bytes", "Replace"):
					if isNegOne(call.Args[3]) {
						report("bytes.ReplaceAll")
					}
				case len(call.Args) == 2 && isPkgSel(info, call.Fun, "bytes", "Map"):
					switch {
					case isPkgSel(info, call.Args[0], "unicode", "ToUpper"):
						report("bytes.ToUpper")
					case isPkgSel(info, call.Args[0], "unicode", "ToLower"):
						report("bytes.ToLower")
					case isPkgSel(info, call.Args[0], "unicode", "ToTitle"):
						report("bytes.ToTitle")
					}
				case len(call.Args) == 7 && isPkgSel(info, call.Fun, "image/draw", "DrawMask"):
					if isIdentNamed(call.Args[4], "nil") {
						if lit, ok := call.Args[5].(*ast.CompositeLit); ok && len(lit.Elts) == 0 && isPkgSel(info, lit.Type, "image", "Point") {
							report("draw.Draw")
						}
					}
				}
			})
			rg.flush()
		}), nil
	})
}

// bytesConvArg returns $x for `[]byte($x)`.
func bytesConvArg(x ast.Expr) ast.Expr {
	call, ok := x.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 || call.Ellipsis.IsValid() {
		return nil
	}
	arr, ok := call.Fun.(*ast.ArrayType)
	if !ok || arr.Len != nil || !isIdentNamed(arr.Elt, "byte") {
		return nil
	}
	return call.Args[0]
}
