	types.Int32:      4,
	types.Int64:      8,
	types.Uint8:      1,
	types.Uint16:     2,
	types.Uint32:     4,
	types.Uint64:     8,
	types.Float32:    4,
	types.Float64:    8,
	types.Complex64:  8,
	types.Complex128: 16,
}

func isSyncAtomicAlign64(T types.Type) bool {
	named, ok := T.(*types.Named)
	if !ok {
		return false
	}
	obj := named.Obj()
	return obj.Name() == "align64" && obj.Pkg() != nil &&
		(obj.Pkg().Path() == "sync/atomic" || obj.Pkg().Path() == "internal/runtime/atomic" || obj.Pkg().Path() == "runtime/internal/atomic")
}

func (s *gcSizes) Alignof(T types.Type) int64 {
	switch t := T.Underlying().(type) {
	case *types.Array:
		return s.Alignof(t.Elem())
	case *types.Struct:
		if t.NumFields() == 0 && isSyncAtomicAlign64(T) {
			return 8
		}
		max := int64(1)
		for i := 0; i < t.NumFields(); i++ {
			if a := s.Alignof(t.Field(i).Type()); a > max {
				max = a
			}
		}
		return max
	case *types.Slice, *types.Interface:
		return s.WordSize
	case *types.Basic:
		if t.Info()&types.IsString != 0 {
			return s.WordSize
		}
	}
	a := s.Sizeof(T)
	if a < 1 {
		return 1
	}
	if b, ok := T.Underlying().(*types.Basic); ok && b.Info()&types.IsComplex != 0 {
		a /= 2
	}
	if a > s.MaxAlign {
		return s.MaxAlign
	}
	return a
}

func alignUp(x, a int64) int64 {
	y := x + a - 1
	return y - y%a
}

func (s *gcSizes) Offsetsof(fields []*types.Var) []int64 {
	offsets := make([]int64, len(fields))
	var offs int64
	for i, f := range fields {
		if offs < 0 {
			offsets[i] = -1
			continue
		}
		a := s.Alignof(f.Type())
		offs = alignUp(offs, a)
		offsets[i] = offs
		if d := s.Sizeof(f.Type()); d >= 0 && offs >= 0 {
			offs += d
		} else {
			offs = -1
		}
	}
	return offsets
}

func (s *gcSizes) Sizeof(T types.Type) int64 {
	switch t := T.Underlying().(type) {
	case *types.Basic:
		k := t.Kind()
		if int(k) < len(basicSizes) {
			if sz := basicSizes[k]; sz > 0 {
				return int64(sz)
			}
		}
		if k == types.String {
			return s.WordSize * 2
		}
	case *types.Array:
		n := t.Len()
		if n <= 0 {
			return 0
		}
		esize := s.Sizeof(t.Elem())
		if esize < 0 {
			return -1
		}
		if esize == 0 {
			return 0
		}
		const maxInt64 = 1<<63 - 1
		if esize > maxInt64/n {
			return -1
		}
		return esize * n
	case *types.Slice:
		return s.WordSize * 3
	case *types.Struct:
		n := t.NumFields()
		if n == 0 {
			return 0
		}
		fields := make([]*types.Var, n)
		for i := range fields {
			fields[i] = t.Field(i)
		}
		offsets := s.Offsetsof(fields)
		offs := offsets[n-1]
		size := s.Sizeof(fields[n-1].Type())
		if offs < 0 || size < 0 {
			return -1
		}
		if offs > 0 && size == 0 {
			size = 1
		}
		return alignUp(offs+size, s.Alignof(T))
	case *types.Interface:
		if _, ok := T.(*types.TypeParam); ok {
			panic("type parameter")
		}
		return s.WordSize * 2
	case *types.Chan, *types.Map, *types.Pointer, *types.Signature:
		return s.WordSize
	}
	return s.WordSize
}

func sizesFor(arch string) types.Sizes {
	switch arch {
	case "386", "arm", "mips", "mipsle", "wasm":
		if arch == "wasm" {
			return &gcSizes{WordSize: 8, MaxAlign: 8}
		}
		return &gcSizes{WordSize: 4, MaxAlign: 4}
	case "amd64p32":
		return &gcSizes{WordSize: 4, MaxAlign: 8}
	}
	return &gcSizes{WordSize: 8, MaxAlign: 8}
}
