import "math/bits"

type sortedHint int

const (
	unknownHint sortedHint = iota
	increasingHint
	decreasingHint
)

type xorshift uint64

var variant = 0

func (r *xorshift) Next() uint64 {
	if variant == 1 {
		*r ^= *r << 13
		*r ^= *r >> 7
		*r ^= *r << 17
		return uint64(*r)
	}
	*r ^= *r << 13
	*r ^= *r >> 17
	*r ^= *r << 5
	return uint64(*r)
}

func nextPowerOfTwo(length int) uint {
	shift := uint(bits.Len(uint(length)))
	return uint(1 << shift)
}
