{"command":"cd /workspace && cat > internal/lint/regex_syntax.go <<'EOF'
package lint

import (
	"errors"
	"strings"
	"unicode/utf8"
)

// A small regular expression parser that builds a syntax tree
// preserving the source text of every node.

type reOp int

const (
	reNone reOp = iota
	reConcat
	reDot
	reAlt
	reStar
	rePlus
	reQuestion
	reNonGreedy
	rePossessive
	reCaret
	reDollar
	reLiteral
	reChar
	reString
	reQuote
	reEscapeChar
	reEscapeMeta
	reEscapeOctal
	reEscapeHex
	reEscapeUni
	reCharClass
	reNegCharClass
	reCharRange
	rePosixClass
	reRepeat
	reCapture
	reNamedCapture
	reGroup
	reGroupWithFlags
	reAtomicGroup
	reLookaround
	reFlagOnlyGroup
	reComment
)

type reExpr struct {
	Op    reOp
	Value string
	Begin int
	End   int
	Args  []*reExpr
}

type reParser struct {
	src      string
	pos      int
	literals bool
}

var errReSyntax = errors.New("regexp syntax error")

func parseRegex(pattern string, literals bool) (re *reExpr, err error) {
	p := &reParser{src: pattern, literals: literals}
	defer func() {
		if r := recover(); r != nil {
			if r == errReSyntax {
				re, err = nil, errReSyntax
				return
			}
			panic(r)
		}
	}()
	e := p.parseAlt()
	if p.pos < len(p.src) {
		// Unexpected ')'.
		panic(errReSyntax)
	}
	return e, nil
}

func (p *reParser) newExpr(op reOp, begin, end int, args ...*reExpr) *reExpr {
	return &reExpr{Op: op, Begin: begin, End: end, Value: p.src[begin:end], Args: args}
}

func (p *reParser) peek() byte {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return 0
}

func (p *reParser) parseAlt() *reExpr {
	branches := []*reExpr{p.parseConcat()}
	for p.pos < len(p.src) && p.src[p.pos] == '|' {
		p.pos++
		branches = append(branches, p.parseConcat())
	}
	if len(branches) == 1 {
		return branches[0]
	}
	return p.newExpr(reAlt, branches[0].Begin, branches[len(branches)-1].End, branches...)
}

func (p *reParser) parseConcat() *reExpr {
	start := p.pos
	var items []*reExpr
	for p.pos < len(p.src) && p.src[p.pos] != '|' && p.src[p.pos] != ')' {
		atom := p.parseAtom()
		atom = p.parseQuantifiers(atom)
		items = append(items, atom)
	}
	if len(items) == 0 {
		return p.newExpr(reConcat, start, start)
	}
	if p.literals {
		items = p.mergeChars(items)
	}
	if len(items) == 1 {
		return items[0]
	}
	return p.newExpr(reConcat, items[0].Begin, items[len(items)-1].End, items...)
}

func (p *reParser) mergeChars(items []*reExpr) []*reExpr {
	var out []*reExpr
	i := 0
	for i < len(items) {
		j := i
		for j < len(items) && items[j].Op == reChar {
			j++
		}
		if j-i > 1 {
			lit := p.newExpr(reLiteral, items[i].Begin, items[j-1].End, items[i:j]...)
			out = append(out, lit)
			i = j
			continue
		}
		out = append(out, items[i])
		i++
	}
	return out
}

func isASCIIDigit(c byte) bool { return c >= '0' && c <= '9' }

// tryRepeat parses {n}, {n,}, {n,m} at current position.
func (p *reParser) tryRepeat() (int, bool) {
	s := p.src[p.pos:]
	if len(s) < 3 || s[0] != '{' {
		return 0, false
	}
	i := 1
	digits := 0
	for i < len(s) && isASCIIDigit(s[i]) {
		i++
		digits++
	}
	if digits == 0 {
		return 0, false
	}
	if i < len(s) && s[i] == ',' {
		i++
		for i < len(s) && isASCIIDigit(s[i]) {
			i++
		}
	}
	if i < len(s) && s[i] == '}' {
		return i + 1, true
	}
	return 0, false
}

func (p *reParser) parseQuantifiers(atom *reExpr) *reExpr {
	for p.pos < len(p.src) {
		c := p.src[p.pos]
		var op reOp
		switch c {
		case '*':
			op = reStar
		case '+':
			op = rePlus
		case '?':
			op = reQuestion
		case '{':
			n, ok := p.tryRepeat()
			if !ok {
				return atom
			}
			count := p.newExpr(reString, p.pos, p.pos+n)
			p.pos += n
			atom = p.newExpr(reRepeat, atom.Begin, p.pos, atom, count)
			atom = p.parseQuantifierSuffix(atom)
			continue
		default:
			return atom
		}
		if isAnchorOrEmpty(atom) {
			panic(errReSyntax)
		}
		p.pos++
		atom = p.newExpr(op, atom.Begin, p.pos, atom)
		atom = p.parseQuantifierSuffix(atom)
	}
	return atom
}

func (p *reParser) parseQuantifierSuffix(q *reExpr) *reExpr {
	if p.peek() == '?' {
		p.pos++
		return p.newExpr(reNonGreedy, q.Begin, p.pos, q)
	}
	return q
}

func isAnchorOrEmpty(e *reExpr) bool {
	return false
}

func (p *reParser) parseAtom() *reExpr {
	start := p.pos
	c := p.src[p.pos]
	switch c {
	case '.':
		p.pos++
		return p.newExpr(reDot, start, p.pos)
	case '^':
		p.pos++
		return p.newExpr(reCaret, start, p.pos)
	case '$':
		p.pos++
		return p.newExpr(reDollar, start, p.pos)
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseClass()
	case '\\':
		return p.parseEscape(false)
	case '*', '+', '?':
		panic(errReSyntax)
	}
	_, size := utf8.DecodeRuneInString(p.src[p.pos:])
	p.pos += size
	return p.newExpr(reChar, start, p.pos)
}

func (p *reParser) parseGroup() *reExpr {
	start := p.pos
	s := p.src[p.pos:]
	var op reOp
	var name *reExpr
	switch {
	case strings.HasPrefix(s, "(?#"):
		end := strings.IndexByte(s, ')')
		if end < 0 {
			panic(errReSyntax)
		}
		p.pos += end + 1
		return p.newExpr(reComment, start, p.pos)
	case strings.HasPrefix(s, "(?:"):
		op = reGroup
		p.pos += 3
	case strings.HasPrefix(s, "(?P<"), strings.HasPrefix(s, "(?<") && !strings.HasPrefix(s, "(?<=") && !strings.HasPrefix(s, "(?<!"):
		skip := 4
		if strings.HasPrefix(s, "(?<") {
			skip = 3
		}
		end := strings.IndexByte(s, '>')
		if end < 0 {
			panic(errReSyntax)
		}
		name = p.newExpr(reString, start+skip, start+end)
		op = reNamedCapture
		p.pos += end + 1
	case strings.HasPrefix(s, "(?="), strings.HasPrefix(s, "(?!"):
		op = reLookaround
		p.pos += 3
	case strings.HasPrefix(s, "(?<="), strings.HasPrefix(s, "(?<!"):
		op = reLookaround
		p.pos += 4
	case strings.HasPrefix(s, "(?>"):
		op = reAtomicGroup
		p.pos += 3
	case strings.HasPrefix(s, "(?"):
		// Flags.
		i := 2
		for i < len(s) && (isFlagChar(s[i])) {
			i++
		}
		if i >= len(s) || i == 2 {
			panic(errReSyntax)
		}
		flags := p.newExpr(reString, start+2, start+i)
		switch s[i] {
		case ')':
			p.pos += i + 1
			return p.newExpr(reFlagOnlyGroup, start, p.pos, flags)
		case ':':
			p.pos += i + 1
			body := p.parseAlt()
			if p.peek() != ')' {
				panic(errReSyntax)
			}
			p.pos++
			return p.newExpr(reGroupWithFlags, start, p.pos, body, flags)
		default:
			panic(errReSyntax)
		}
	default:
		op = reCapture
		p.pos++
	}
	body := p.parseAlt()
	if p.peek() != ')' {
		panic(errReSyntax)
	}
	p.pos++
	if name != nil {
		return p.newExpr(op, start, p.pos, body, name)
	}
	return p.newExpr(op, start, p.pos, body)
}

func isFlagChar(c byte) bool {
	switch c {
	case 'i', 'm', 's', 'U', '-':
		return true
	}
	return false
}

const reOutsideMeta = `|*+?.[]^$(){}\`

func (p *reParser) parseEscape(inClass bool) *reExpr {
	start := p.pos
	if p.pos+1 >= len(p.src) {
		panic(errReSyntax)
	}
	c := p.src[p.pos+1]
	switch {
	case c == 'x':
		p.pos += 2
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				panic(errReSyntax)
			}
			p.pos += end + 1
		} else {
			if p.pos+2 > len(p.src) {
				panic(errReSyntax)
			}
			p.pos += 2
		}
		return p.newExpr(reEscapeHex, start, p.pos)
	case c == 'p' || c == 'P':
		p.pos += 2
		if p.peek() == '{' {
			end := strings.IndexByte(p.src[p.pos:], '}')
			if end < 0 {
				panic(errReSyntax)
			}
			p.pos += end + 1
		} else {
			if p.pos >= len(p.src) {
				panic(errReSyntax)
			}
			_, size := utf8.DecodeRuneInString(p.src[p.pos:])
			p.pos += size
		}
		return p.newExpr(reEscapeUni, start, p.pos)
	case c >= '0' && c <= '7':
		p.pos += 2
		for n := 1; n < 3 && p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '7'; n++ {
			p.pos++
		}
		return p.newExpr(reEscapeOctal, start, p.pos)
	case c == 'Q' && !inClass:
		p.pos += 2
		end := strings.Index(p.src[p.pos:], `\E`)
		if end < 0 {
			p.pos = len(p.src)
		} else {
			p.pos += end + 2
		}
		return p.newExpr(reQuote, start, p.pos)
	}
	_, size := utf8.DecodeRuneInString(p.src[p.pos+1:])
	p.pos += 1 + size
	if inClass {
		if c == '-' || c == ']' {
			return p.newExpr(reEscapeMeta, start, p.pos)
		}
		return p.newExpr(reEscapeChar, start, p.pos)
	}
	if strings.IndexByte(reOutsideMeta, c) >= 0 {
		return p.newExpr(reEscapeMeta, start, p.pos)
	}
	return p.newExpr(reEscapeChar, start, p.pos)
}

func (p *reParser) parseClassAtom() *reExpr {
	start := p.pos
	if p.pos >= len(p.src) {
		panic(errReSyntax)
	}
	if p.src[p.pos] == '\\' {
		return p.parseEscape(true)
	}
	_, size := utf8.DecodeRuneInString(p.src[p.pos:])
	p.pos += size
	return p.newExpr(reChar, start, p.pos)
}

func canBeRangeBound(e *reExpr) bool {
	switch e.Op {
	case reChar, reEscapeHex, reEscapeOctal, reEscapeMeta:
		return true
	}
	return false
}

func (p *reParser) parseClass() *reExpr {
	start := p.pos
	p.pos++
	op := reCharClass
	if p.peek() == '^' {
		op = reNegCharClass
		p.pos++
	}
	var items []*reExpr
	first := true
	for {
		if p.pos >= len(p.src) {
			panic(errReSyntax)
		}
		c := p.src[p.pos]
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		if c == '[' && strings.HasPrefix(p.src[p.pos:], "[:") {
			if end := strings.Index(p.src[p.pos+2:], ":]"); end >= 0 {
				b := p.pos
				p.pos += 2 + end + 2
				items = append(items, p.newExpr(rePosixClass, b, p.pos))
				continue
			}
		}
		item := p.parseClassAtom()
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' && canBeRangeBound(item) {
			save := p.pos
			p.pos++
			hi := p.parseClassAtom()
			if canBeRangeBound(hi) {
				item = p.newExpr(reCharRange, item.Begin, hi.End, item, hi)
			} else {
				p.pos = save
			}
		}
		items = append(items, item)
	}
	return p.newExpr(op, start, p.pos, items...)
}
EOF
