					return true
				}
				s := &reSimplifier{}
				simplified := s.simplify(pat)
				if simplified == "" {
					return true
				}
				if s2 := s.simplify(simplified); s2 != "" {
					simplified = s2
				}
				ctx.Warn(call.Args[0], "can re-write `%s` as `%s`", pat, simplified)
				return true
			})
		}), nil
	})
}

type reSimplifier struct {
	out   strings.Builder
	score int
}

func (c *reSimplifier) simplify(pat string) string {
	re, err := parseRegex(pat, false)
	if err != nil {
		return ""
	}
	c.score = 0
	c.out.Reset()
	c.walk(re)
	if c.score > 0 {
		return c.out.String()
	}
	return ""
}

func (c *reSimplifier) walk(e *reExpr) {
	out := &c.out
	switch e.Op {
	case reConcat:
		c.walkConcat(e)
	case reAlt:
		c.walkAlt(e)
	case reCharRange:
		if s := c.simplifyCharRange(e); s != "" {
			out.WriteString(s)
			c.score++
		} else {
			out.WriteString(e.Value)
		}
	case reGroupWithFlags:
		out.WriteString("(")
		out.WriteString(e.Args[1].Value)
		out.WriteString(":")
		c.walk(e.Args[0])
		out.WriteString(")")
	case reGroup:
		c.walkGroup(e)
	case reCapture:
		out.WriteString("(")
		c.walk(e.Args[0])
		out.WriteString(")")
	case reNamedCapture:
		out.WriteString("(?P<")
		out.WriteString(e.Args[1].Value)
		out.WriteString(">")
		c.walk(e.Args[0])
		out.WriteString(")")
	case reRepeat:
		rep := e.Args[1].Value
		switch rep {
		case "{0,}":
			c.walk(e.Args[0])
			out.WriteString("*")
			c.score++
		case "{1,}":
			c.walk(e.Args[0])
			out.WriteString("+")
			c.score++
		case "{0,1}":
			c.walk(e.Args[0])
			out.WriteString("?")
			c.score++
		case "{1}":
			c.walk(e.Args[0])
			c.score++
		default:
			c.walk(e.Args[0])
			out.WriteString(rep)
		}
	case reNegCharClass:
		if s := c.simplifyNegCharClass(e); s != "" {
			out.WriteString(s)
			c.score++
		} else {
			out.WriteString("[^")
			for _, a := range e.Args {
				c.walk(a)
			}
			out.WriteString("]")
		}
	case reCharClass:
		if s := c.simplifyCharClass(e); s != "" {
			out.WriteString(s)
			c.score++
		} else {
			out.WriteString("[")
			for _, a := range e.Args {
				c.walk(a)
			}
			out.WriteString("]")
		}
	case reEscapeChar:
		switch e.Value {
		case `\&`, `\#`, `\!`, `\@`, `\%`, `\<`, `\>`, `\:`, `\;`, `\/`, `\,`, `\=`:
			c.score++
			out.WriteString(e.Value[len(`\`):])
		default:
			out.WriteString(e.Value)
		}
	case reQuestion:
		c.walk(e.Args[0])
		out.WriteString("?")
	case reNonGreedy:
		c.walk(e.Args[0])
		out.WriteString("?")
	case reStar:
		c.walk(e.Args[0])
		out.WriteString("*")
	case rePlus:
		c.walk(e.Args[0])
		out.WriteString("+")
	default:
		out.WriteString(e.Value)
	}
}

func (c *reSimplifier) walkGroup(g *reExpr) {
	switch g.Args[0].Op {
	case reChar, reEscapeChar, reEscapeMeta, reCharClass:
		c.walk(g.Args[0])
		c.score++
		return
	}
	c.out.WriteString("(?:")
	c.walk(g.Args[0])
	c.out.WriteString(")")
}

func (c *reSimplifier) simplifyNegCharClass(e *reExpr) string {
	switch e.Value {
	case `[^0-9]`:
		return `\D`
	case `[^\s]`:
		return `\S`
	case `[^\S]`:
		return `\s`
	case `[^\w]`:
		return `\W`
	case `[^\W]`:
		return `\w`
	case `[^\d]`:
		return `\D`
	case `[^\D]`:
		return `\d`
	case `[^[:^space:]]`:
		return `\s`
	case `[^[:space:]]`:
		return `\S`
	case `[^[:^word:]]`:
		return `\w`
	case `[^[:word:]]`:
		return `\W`
	case `[^[:^digit:]]`:
		return `\d`
	case `[^[:digit:]]`:
		return `\D`
	}
	return ""
}

func (c *reSimplifier) simplifyCharClass(e *reExpr) string {
	switch e.Value {
	case `[0-9]`:
		return `\d`
	case `[[:word:]]`:
		return `\w`
	case `[[:^word:]]`:
		return `\W`
	case `[[:digit:]]`:
		return `\d`
	case `[[:^digit:]]`:
		return `\D`
	case `[[:space:]]`:
		return `\s`
	case `[[:^space:]]`:
		return `\S`
	case `[][]`:
		return `\]\[`
	case `[]]`:
		return `\]`
	}
	if len(e.Args) == 1 {
		switch e.Args[0].Op {
		case reChar:
			switch v := e.Args[0].Value; v {
			case "|", "*", "+", "?", ".", "[", "^", "$", "(", ")":
			default:
				return v
			}
		case reEscapeChar:
			return e.Args[0].Value
		}
	}
	return ""
}

func (c *reSimplifier) canMerge(x, y *reExpr) bool {
	if x.Op != y.Op {
		return false
	}
	switch x.Op {
	case reChar, reCharClass, reEscapeMeta, reEscapeChar, reNegCharClass, reGroup:
		return x.Value == y.Value
	}
	return false
}

func (c *reSimplifier) canCombine(x, y *reExpr) (int, bool) {
	if x.Op != y.Op {
		return 0, false
	}
	switch x.Op {
	case reDot:
		return 3, true
	case reChar:
		if x.Value != y.Value {
			return 0, false
		}
		if x.Value == " " {
			return 1, true
		}
		return 4, true
	case reEscapeMeta, reEscapeChar:
		if x.Value == y.Value {
			return 2, true
		}
	case reCharClass, reNegCharClass, reGroup:
		if x.Value == y.Value {
			return 1, true
		}
	}
	return 0, false
}

func (c *reSimplifier) allChars(e *reExpr) bool {
	for _, a := range e.Args {
		if a.Op != reChar {
			return false
		}
	}
	return true
}

func (c *reSimplifier) walkAlt(alt *reExpr) {
	if c.allChars(alt) {
		c.score++
		c.out.WriteString("[")
		for _, a := range alt.Args {
			c.out.WriteString(a.Value)
		}
		c.out.WriteString("]")
		return
	}
	for i, a := range alt.Args {
		c.walk(a)
		if i != len(alt.Args)-1 {
			c.out.WriteString("|")
		}
	}
}

func (c *reSimplifier) walkConcat(concat *reExpr) {
	i := 0
	for i < len(concat.Args) {
		x := concat.Args[i]
		c.walk(x)
		i++
		if i >= len(concat.Args) {
			break
		}
		if concat.Args[i].Op == reStar {
			if c.canMerge(x, concat.Args[i].Args[0]) {
				c.out.WriteString("+")
				c.score++
				i++
				continue
			}
		}
		threshold, ok := c.canCombine(x, concat.Args[i])
		if !ok {
			continue
		}
		n := 1
		for j := i + 1; j < len(concat.Args); j++ {
			if _, ok := c.canCombine(x, concat.Args[j]); !ok {
				break
			}
			n++
		}
		if n >= threshold {
			fmt.Fprintf(&c.out, "{%d}", n+1)
			c.score++
			i += n
		}
	}
}

func (c *reSimplifier) simplifyCharRange(rng *reExpr) string {
	if rng.Args[0].Op != reChar || rng.Args[1].Op != reChar {
		return ""
	}
	lo := rng.Args[0].Value
	hi := rng.Args[1].Value
	if len(lo) == 1 && len(hi) == 1 {
		switch int(hi[0]) - int(lo[0]) {
		case 0:
			return lo
		case 1:
			return lo + hi
		case 2:
			return lo + string(lo[0]+1) + hi
		}
	}
	return ""
}
