			if isCharOrLit(a) {
				matched++
			}
		}
		if matched == len(alt.Args)-1 {
			r.warn("^ applied only to `%s` in %s", first.Value[len(`^`):], alt.Value)
		}
	}
	last := alt.Args[len(alt.Args)-1]
	if last.Op == reConcat && len(last.Args) == 2 && last.Args[1].Op == reDollar && isCharOrLit(last.Args[0]) {
		matched := 0
		for _, a := range alt.Args[:len(alt.Args)-1] {
			if isCharOrLit(a) {
				matched++
			}
		}
		if matched == len(alt.Args)-1 {
			r.warn("$ applied only to `%s` in %s", last.Value[:len(last.Value)-len(`$`)], alt.Value)
		}
	}
}

type reCharRangeItem struct {
	low, high rune
	source    string
}

// classItemRune decodes a single class element into a rune.
// The second result is 0 for success, 1 for "ignore", 2 for "abort".
func classItemRune(e *reExpr) (rune, int) {
	switch e.Op {
	case reChar:
		r, _ := utf8.DecodeRuneInString(e.Value)
		return r, 0
	case reEscapeHex:
		s := e.Value[len(`\x`):]
		if strings.HasPrefix(s, "{") {
			s = strings.TrimSuffix(s[1:], "}")
		}
		v, err := strconv.ParseInt(s, 16, 32)
		if err != nil {
			return 0, 2
		}
		return rune(v), 0
	case reEscapeOctal:
		v, err := strconv.ParseInt(e.Value[1:], 8, 32)
		if err != nil {
			return 0, 2
		}
		return rune(v), 0
	case reEscapeMeta, reEscapeChar:
		switch e.Value {
		case `\n`:
			return '\n', 0
		case `\t`:
			return '\t', 0
		case `\r`:
			return '\r', 0
		case `\D`, `\S`, `\W`, `\v`, `\f`:
			return 0, 1
		case `\$`, `\^`, `\~`, `\ `, `\a`:
			return 0, 2
		}
		rest := e.Value[1:]
		ch, size := utf8.DecodeRuneInString(rest)
		if size != len(rest) {
			return 0, 2
		}
		if strings.ContainsRune(".-][\\*|+?(){}/&!#\"',:;<>=@%_", ch) {
			return ch, 0
		}
		return 0, 2
	}
	return 0, 2
}

func (r *badRegexpRun) checkCharClassRanges(cc *reExpr) bool {
	var ranges []reCharRangeItem
	add := func(lo, hi rune, src string) {
		ranges = append(ranges, reCharRangeItem{lo, hi, src})
	}
	for _, e := range cc.Args {
		switch {
		case e.Op == reCharRange:
			lo, s1 := classItemRune(e.Args[0])
			hi, s2 := classItemRune(e.Args[1])
			if s1 != 0 || s2 != 0 {
				return false
			}
			add(lo, hi, e.Value)
		case e.Op == reEscapeChar && e.Value == `\d`:
			add('0', '9', e.Value)
		case e.Op == reEscapeChar && e.Value == `\w`:
			add('0', '9', e.Value)
			add('A', 'Z', e.Value)
			add('_', '_', e.Value)
			add('a', 'z', e.Value)
		case e.Op == reEscapeChar && e.Value == `\s`:
			add('\t', '\r', e.Value)
			add(' ', ' ', e.Value)
		default:
			ch, status := classItemRune(e)
			switch status {
			case 0:
				add(ch, ch, e.Value)
			case 1:
				// ignore
			default:
				return false
			}
		}
	}
	pdqSortSlice(len(ranges),
		func(i, j int) bool { return ranges[i].low < ranges[j].low },
		func(i, j int) { ranges[i], ranges[j] = ranges[j], ranges[i] })
	for i := 0; i < len(ranges)-1; i++ {
		x, y := ranges[i], ranges[i+1]
		if x.source == y.source {
			continue
		}
		if x.high >= y.low {
			r.warn("`%s` intersects with `%s` in %s", x.source, y.source, cc.Value)
			return false
		}
	}
	return true
}

func (r *badRegexpRun) checkCharClassDups(cc *reExpr) {
	if len(cc.Args) == 1 {
		return
	}
	set := map[string]bool{}
	for _, e := range cc.Args {
		if set[e.Value] {
			r.warn("`%s` is duplicated in %s", e.Value, cc.Value)
			return
		}
		set[e.Value] = true
	}
}
EOF
