type ruleguardEngine struct {
	loaded int
}

type ruleguardError struct {
	kind string // "dsl" or "import"
	msg  string
}

func (e *ruleguardError) Error() string { return e.msg }

func parseRuleguardFailOn(failOn string, failOnError bool) (map[string]bool, error) {
	res := map[string]bool{}
	if failOnError {
		res["all"] = true
	}
	if failOn == "" {
		return res, nil
	}
	for _, s := range strings.Split(failOn, ",") {
		switch s {
		case "dsl", "import", "all":
			res[s] = true
		default:
			return nil, fmt.Errorf("ruleguard init error: 'failOnError' flag '%s' is invalid. It must be a comma-separated list and supported values are 'dsl,import,all'", s)
		}
	}
	return res, nil
}

func loadRuleguardFiles(ctx *CheckerContext, files []string, failOn map[string]bool) (*ruleguardEngine, error) {
	e := &ruleguardEngine{}
	for _, filename := range files {
		err := loadRuleguardFile(filename)
		if err == nil {
			e.loaded++
			continue
		}
		if failOn["all"] || failOn[err.kind] {
			return nil, fmt.Errorf("ruleguard init error: %s", err.msg)
		}
		log.Printf("ruleguard init error, skip %s: %s", filename, err.msg)
	}
	return e, nil
}

func loadRuleguardFile(filename string) *ruleguardError {
	src, err := os.ReadFile(filename)
	if err != nil {
		return &ruleguardError{kind: "dsl", msg: fmt.Sprintf("read file error: %v", err)}
	}
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, src, parser.ParseComments)
	if err != nil {
		return &ruleguardError{kind: "dsl", msg: fmt.Sprintf("parse file error: %v", err)}
	}
	conf := types.Config{Importer: newRuleguardImporter(fset, filepath.Dir(filename))}
	if _, err := conf.Check("gorules", fset, []*ast.File{f}, &types.Info{}); err != nil {
		return &ruleguardError{kind: "dsl", msg: fmt.Sprintf("typechecker error: %v", err)}
