// TypeCheckAll parses and type-checks all given root packages.
// Imports between root packages are resolved to the source-checked packages.
func TypeCheckAll(fset *token.FileSet, all, pkgs []*Package) {
	u := &universe{
		fset:     fset,
		roots:    map[string]*Package{},
		srcCache: map[string]*types.Package{},
		visiting: map[string]bool{},
	}
	for _, pkg := range all {
		if len(pkg.Files) != 0 {
			u.roots[pkg.ID] = pkg
		}
		if u.byID == nil {
			u.byID = pkg.byID
		}
		u.sizes = pkg.Sizes
	}
	for _, pkg := range pkgs {
		u.checkRoot(pkg)
	}
}

func (u *universe) checkRoot(pkg *Package) {
	if pkg.parsed {
		return
	}
	pkg.parsed = true
	for _, filename := range pkg.Files {
		src, err := os.ReadFile(filename)
		if err != nil {
			continue
		}
		f, _ := parser.ParseFile(u.fset, filename, src, parser.AllErrors|parser.ParseComments)
		if f == nil {
			continue
		}
		pkg.Syntax = append(pkg.Syntax, f)
		pkg.Sources = append(pkg.Sources, src)
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Scopes:     map[ast.Node]*types.Scope{},
		Instances:  map[*ast.Ident]types.Instance{},
	}
	conf := u.config(pkg.lp, pkg.ID)
	tpkg, _ := conf.Check(pkg.PkgPath, u.fset, pkg.Syntax, info)
	if tpkg == nil {
		tpkg = types.NewPackage(pkg.PkgPath, pkg.Name)
	}
	pkg.Types = tpkg
	pkg.TypesInfo = info
}

func (u *universe) config(lp *listPackage, selfID string) types.Config {
	conf := types.Config{
		Importer: &depImporter{u: u, lp: lp, selfID: selfID},
		Error:    func(error) {},
		Sizes:    u.sizes,
	}
	if lp.Module != nil && lp.Module.GoVersion != "" {
		conf.GoVersion = "go" + lp.Module.GoVersion
	}
	return conf
}

// checkFromSource type-checks a dependency without export data.
func (u *universe) checkFromSource(lp *listPackage) *types.Package {
	id := lp.ImportPath
	if pkg, ok := u.srcCache[id]; ok {
		return pkg
	}
	if u.visiting[id] {
		return nil
	}
	u.visiting[id] = true
	defer delete(u.visiting, id)
	files := lp.CompiledGoFiles
	if len(files) == 0 {
		files = lp.GoFiles
	}
	var syntax []*ast.File
	for _, f := range files {
		if !filepath.IsAbs(f) {
			f = filepath.Join(lp.Dir, f)
		}
		af, _ := parser.ParseFile(u.fset, f, nil, 0)
		if af != nil {
			syntax = append(syntax, af)
		}
	}
	conf := u.config(lp, id)
	conf.IgnoreFuncBodies = true
	tpkg, _ := conf.Check(pkgPathOf(lp), u.fset, syntax, nil)
	u.srcCache[id] = tpkg
	return tpkg
}

