package lint

import (
	"go/ast"
)

func init() {
	register("flagDeref", func(ctx *CheckerContext) (FileWalker, error) {
		funcs := map[string]bool{
			"Bool":     true,
			"Duration": true,
			"Float64":  true,
			"Int":      true,
			"Int64":    true,
			"String":   true,
			"Uint":     true,
			"Uint64":   true,
		}
		return walkerFunc(func(f *ast.File) {
			info := ctx.TypesInfo
			rg := newRG(ctx)
			walkAll(f, func(n ast.Node) {
				star, ok := n.(*ast.StarExpr)
				if !ok {
					return
				}
				call, ok := star.X.(*ast.CallExpr)
				if !ok || call.Ellipsis.IsValid() {
					return
				}
				name := pkgSelName(info, call.Fun, "flag")
				if !funcs[name] {
					return
				}
				rg.report(star, "immediate deref in "+rg.text(star)+" is most likely an error; consider using flag."+name+"Var")
			})
			rg.flush()
		}), nil
	})
}
EOF
