s+='''
// wrapperFuncCheckCutList matches `$i := strings.Index($s, $sep); ...; $x = $s[:$i]; ...; $y = $s[$i+1:]`.
func wrapperFuncCheckCutList(ctx *CheckerContext, rg *rgRunner, list []ast.Stmt) {
	if !ctx.GoVersion.GreaterOrEqual(GoVersion{1, 18}) {
		return
	}
	info := ctx.TypesInfo
	for k, st := range list {
		init, ok := st.(*ast.AssignStmt)
		if !ok || init.Tok != token.DEFINE || len(init.Lhs) != 1 || len(init.Rhs) != 1 {
			continue
		}
		i, ok := init.Lhs[0].(*ast.Ident)
		if !ok {
			continue
		}
		call, ok := init.Rhs[0].(*ast.CallExpr)
		if !ok || len(call.Args) != 2 || call.Ellipsis.IsValid() || !isPkgSel(info, call.Fun, "strings", "Index") {
			continue
		}
		s, sep := call.Args[0], call.Args[1]
		x, y := cutAssignments(s, i, list[k+1:])
		if x == nil {
			continue
		}
		rg.report(st, "suggestion: "+rg.text(x)+", "+rg.text(y)+", _ = strings.Cut("+rg.text(s)+", "+rg.text(sep)+")")
	}
}

// cutAssignments finds `$x, $y = $s[:$i], $s[$i+1:]` or `$x = $s[:$i]; ...; $y = $s[$i+1:]`.
func cutAssignments(s ast.Expr, i *ast.Ident, list []ast.Stmt) (ast.Expr, ast.Expr) {
	isBefore := func(x ast.Expr) bool {
		sl, ok := x.(*ast.SliceExpr)
		return ok && !sl.Slice3 && sl.Low == nil && sl.Max == nil && sl.High != nil &&
			astEqual(sl.X, s) && astEqual(sl.High, i)
	}
	isAfter := func(x ast.Expr) bool {
		sl, ok := x.(*ast.SliceExpr)
		if !ok || sl.Slice3 || sl.High != nil || sl.Max != nil || sl.Low == nil || !astEqual(sl.X, s) {
			return false
		}
		bin, ok := sl.Low.(*ast.BinaryExpr)
		return ok && bin.Op == token.ADD && astEqual(bin.X, i) && isIntLit(bin.Y, 1)
	}
	assign := func(st ast.Stmt) *ast.AssignStmt {
		a, ok := st.(*ast.AssignStmt)
		if !ok || a.Tok != token.ASSIGN {
			return nil
		}
		return a
	}
	for _, st := range list {
		a := assign(st)
		if a != nil && len(a.Lhs) == 2 && len(a.Rhs) == 2 && isBefore(a.Rhs[0]) && isAfter(a.Rhs[1]) {
			return a.Lhs[0], a.Lhs[1]
		}
	}
	for k, st := range list {
		a := assign(st)
		if a == nil || len(a.Lhs) != 1 || len(a.Rhs) != 1 || !isBefore(a.Rhs[0]) {
			continue
		}
		for _, st2 := range list[k+1:] {
			b := assign(st2)
			if b != nil && len(b.Lhs) == 1 && len(b.Rhs) == 1 && isAfter(b.Rhs[0]) {
				return a.Lhs[0], b.Lhs[0]
			}
		}
	}
	return nil, nil
}
'''
